module.exports = "<!DOCTYPE html>\n<html lang=\"pt-BR\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n  <title>IPTV CLIENTES - Painel de Controle</title>\n  <link rel=\"manifest\" href=\"/manifest.json\">\n  <meta name=\"theme-color\" content=\"#0d55bc\">\n  <script src=\"https://cdn.tailwindcss.com\"></script>\n  <script>\n    tailwind.config = {\n      theme: {\n        extend: {\n          colors: {\n            brand: {\n              blue: '#0d55bc',\n              darkblue: '#0a3a82',\n              hoverblue: '#0a469e',\n              gold: '#ffb703',\n              orange: '#f59e0b',\n              ice: '#f0f5fc'\n            }\n          }\n        }\n      }\n    }\n  </script>\n  <link href=\"https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800;900&display=swap\" rel=\"stylesheet\">\n  <link rel=\"stylesheet\" href=\"https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.4.0/css/all.min.css\">\n  <link rel=\"stylesheet\" href=\"css/style.css\">\n</head>\n<body class=\"bg-[#f0f5fc] text-black font-sans min-h-screen flex flex-col antialiased text-base\">\n\n  <!-- TOP NAVBAR COM AS CORES OFICIAIS DA LOGO (ROYAL BLUE & GOLD) -->\n  <header class=\"bg-white border-b-4 border-[#0d55bc] sticky top-0 z-40 px-6 py-3.5 shadow-md\">\n    <div class=\"max-w-7xl mx-auto flex justify-between items-center\">\n      <!-- Logo & Company Name -->\n      <div class=\"flex items-center space-x-4\">\n        <div id=\"headerLogoBox\" class=\"min-w-[60px] max-w-[200px] h-14 p-1 rounded-2xl bg-white border-2 border-[#0d55bc] flex items-center justify-center text-[#0d55bc] font-black text-2xl shadow-sm overflow-hidden relative shrink-0\">\n          <i id=\"headerLogoIcon\" class=\"fa-solid fa-tv text-2xl text-[#0d55bc]\"></i>\n          <img id=\"headerLogoImg\" class=\"hidden max-h-12 w-auto object-contain p-0.5\" alt=\"Logo da Empresa\">\n        </div>\n        <div>\n          <h1 id=\"headerCompanyName\" class=\"font-black text-2xl tracking-tight text-black flex items-center gap-2 leading-tight\">\n            IPTV CLIENTES\n          </h1>\n        </div>\n      </div>\n\n      <!-- WhatsApp Connection Status Badge & Actions -->\n      <div class=\"flex items-center space-x-4\">\n        <div id=\"waStatusBadge\" class=\"flex items-center space-x-2.5 px-4 py-2 rounded-full bg-[#efe8dc] border border-[#e2d7c5] text-sm font-bold\">\n          <span class=\"w-3 h-3 rounded-full bg-yellow-500 animate-pulse\" id=\"waStatusDot\"></span>\n          <span id=\"waStatusText\" class=\"text-slate-800\">Conectando WhatsApp...</span>\n        </div>\n\n\n\n        <button onclick=\"openClientModal()\" class=\"hidden md:flex items-center space-x-2 bg-gradient-to-r from-brand-orange to-brand-orangeDark hover:from-brand-orangeDark hover:to-orange-700 text-white font-bold text-sm px-5 py-2.5 rounded-xl shadow-md transition transform hover:scale-105\">\n          <i class=\"fa-solid fa-plus\"></i>\n          <span>Novo Cliente</span>\n        </button>\n      </div>\n    </div>\n  </header>\n\n  <!-- MAIN WRAPPER -->\n  <div class=\"max-w-7xl mx-auto w-full flex-1 flex flex-col md:flex-row gap-6 p-4 md:p-6\">\n\n    <!-- SIDEBAR NAVIGATION -->\n    <aside class=\"w-full md:w-64 flex flex-row md:flex-col gap-2.5 overflow-x-auto pb-2 md:pb-0\">\n      <button onclick=\"switchTab('dashboard')\" id=\"tabBtn-dashboard\" class=\"nav-tab active flex items-center space-x-3 px-5 py-3.5 rounded-xl font-bold text-base transition\">\n        <i class=\"fa-solid fa-chart-pie w-6 text-xl\"></i>\n        <span>Dashboard</span>\n      </button>\n\n      <button onclick=\"switchTab('clients')\" id=\"tabBtn-clients\" class=\"nav-tab flex items-center space-x-3 px-5 py-3.5 rounded-xl font-bold text-base transition\">\n        <i class=\"fa-solid fa-users text-brand-orange w-6 text-xl\"></i>\n        <span>Clientes (CRM)</span>\n      </button>\n\n      <button onclick=\"switchTab('plans')\" id=\"tabBtn-plans\" class=\"nav-tab flex items-center space-x-3 px-5 py-3.5 rounded-xl font-bold text-base transition\">\n        <i class=\"fa-solid fa-tv text-sky-600 w-6 text-xl\"></i>\n        <span>Cards de Planos</span>\n      </button>\n\n      <button onclick=\"switchTab('apps_servers')\" id=\"tabBtn-apps_servers\" class=\"nav-tab flex items-center space-x-3 px-5 py-3.5 rounded-xl font-bold text-base transition\">\n        <i class=\"fa-solid fa-mobile-screen-button text-purple-600 w-6 text-xl\"></i>\n        <span>Apps & Servidores</span>\n      </button>\n\n      <button onclick=\"switchTab('whatsapp')\" id=\"tabBtn-whatsapp\" class=\"nav-tab flex items-center space-x-3 px-5 py-3.5 rounded-xl font-bold text-base transition\">\n        <i class=\"fa-brands fa-whatsapp text-emerald-600 w-6 text-xl\"></i>\n        <span>Conectar WhatsApp</span>\n      </button>\n\n      <button onclick=\"switchTab('ai_prompt')\" id=\"tabBtn-ai_prompt\" class=\"nav-tab flex items-center space-x-3 px-5 py-3.5 rounded-xl font-bold text-base transition\">\n        <i class=\"fa-solid fa-robot text-brand-blue w-6 text-xl\"></i>\n        <span>IA & Prompt</span>\n      </button>\n\n      <button onclick=\"switchTab('interactive_menu')\" id=\"tabBtn-interactive_menu\" class=\"nav-tab flex items-center space-x-3 px-5 py-3.5 rounded-xl font-bold text-base transition\">\n        <i class=\"fa-solid fa-list-check text-purple-600 w-6 text-xl\"></i>\n        <span>Menu Automático</span>\n      </button>\n\n      <button onclick=\"switchTab('receipts')\" id=\"tabBtn-receipts\" class=\"nav-tab flex items-center space-x-3 px-5 py-3.5 rounded-xl font-bold text-base transition\">\n        <i class=\"fa-solid fa-receipt text-amber-600 w-6 text-xl\"></i>\n        <span>Recibos & Disparos</span>\n      </button>\n\n      <button onclick=\"switchTab('settings')\" id=\"tabBtn-settings\" class=\"nav-tab flex items-center space-x-3 px-5 py-3.5 rounded-xl font-bold text-base transition\">\n        <i class=\"fa-solid fa-gear text-slate-600 w-6 text-xl\"></i>\n        <span>Configurações</span>\n      </button>\n    </aside>\n\n    <!-- CONTENT AREA -->\n    <main class=\"flex-1 min-w-0\">\n\n      <!-- 1. TAB: DASHBOARD -->\n      <section id=\"tab-dashboard\" class=\"tab-content block space-y-6\">\n\n\n        <!-- Stats Cards -->\n        <div class=\"grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-5\">\n          <div class=\"bg-white border border-[#e2d7c5] p-6 rounded-2xl shadow-sm relative overflow-hidden\">\n            <div class=\"flex items-center justify-between\">\n              <div>\n                <p class=\"text-sm font-bold text-slate-500 uppercase tracking-wider\">Total de Clientes</p>\n                <h3 id=\"statTotalClients\" class=\"text-3xl font-extrabold text-slate-900 mt-1\">0</h3>\n              </div>\n              <div class=\"w-12 h-12 rounded-xl bg-brand-blue/10 text-brand-blue flex items-center justify-center text-2xl font-bold\">\n                <i class=\"fa-solid fa-users\"></i>\n              </div>\n            </div>\n          </div>\n\n          <div class=\"bg-white border border-[#e2d7c5] p-6 rounded-2xl shadow-sm relative overflow-hidden\">\n            <div class=\"flex items-center justify-between\">\n              <div>\n                <p class=\"text-sm font-bold text-slate-500 uppercase tracking-wider\">Planos Ativos</p>\n                <h3 id=\"statActiveClients\" class=\"text-3xl font-extrabold text-emerald-600 mt-1\">0</h3>\n              </div>\n              <div class=\"w-12 h-12 rounded-xl bg-emerald-500/10 text-emerald-600 flex items-center justify-center text-2xl font-bold\">\n                <i class=\"fa-solid fa-circle-check\"></i>\n              </div>\n            </div>\n          </div>\n\n          <div class=\"bg-white border border-[#e2d7c5] p-6 rounded-2xl shadow-sm relative overflow-hidden\">\n            <div class=\"flex items-center justify-between\">\n              <div>\n                <p class=\"text-sm font-bold text-slate-500 uppercase tracking-wider\">Vencem em 3d</p>\n                <h3 id=\"statExpiringClients\" class=\"text-3xl font-extrabold text-brand-orange mt-1\">0</h3>\n              </div>\n              <div class=\"w-12 h-12 rounded-xl bg-brand-orange/10 text-brand-orange flex items-center justify-center text-2xl font-bold\">\n                <i class=\"fa-solid fa-clock\"></i>\n              </div>\n            </div>\n          </div>\n\n          <div class=\"bg-white border border-[#e2d7c5] p-6 rounded-2xl shadow-sm relative overflow-hidden\">\n            <div class=\"flex items-center justify-between\">\n              <div>\n                <p class=\"text-sm font-bold text-slate-500 uppercase tracking-wider\">Planos Atrasados</p>\n                <h3 id=\"statExpiredClients\" class=\"text-3xl font-extrabold text-red-600 mt-1\">0</h3>\n              </div>\n              <div class=\"w-12 h-12 rounded-xl bg-red-500/10 text-red-600 flex items-center justify-center text-2xl font-bold\">\n                <i class=\"fa-solid fa-circle-exclamation\"></i>\n              </div>\n            </div>\n          </div>\n        </div>\n\n        <!-- ALERTS SECTION: EXPIRING TOMORROW & EXPIRED CLIENTS -->\n        <div id=\"alertsContainer\" class=\"space-y-4\">\n          <!-- Alerta Urgente: Falta 1 Dia -->\n          <div id=\"alertOneDayBox\" class=\"hidden bg-amber-50 border-2 border-amber-400 p-5 rounded-2xl shadow-sm\">\n            <div class=\"flex items-center justify-between mb-3\">\n              <h3 class=\"text-base font-extrabold text-amber-900 flex items-center gap-2\">\n                <i class=\"fa-solid fa-triangle-exclamation text-amber-600 text-xl animate-bounce\"></i>\n                <span>ALERTA URGENTE: Clientes com Vencimento AMANHÃ (Falta 1 Dia!)</span>\n              </h3>\n              <span id=\"alertOneDayCount\" class=\"bg-amber-500 text-white font-extrabold text-xs px-3 py-1 rounded-full\">0 Clientes</span>\n            </div>\n            <div id=\"alertOneDayList\" class=\"space-y-2\">\n              <!-- Renderizado via JS -->\n            </div>\n          </div>\n\n          <!-- Alerta Crítico: Planos Atrasados / Vencidos -->\n          <div id=\"alertExpiredBox\" class=\"hidden bg-red-50 border-2 border-red-400 p-5 rounded-2xl shadow-sm\">\n            <div class=\"flex items-center justify-between mb-3\">\n              <h3 class=\"text-base font-extrabold text-red-900 flex items-center gap-2\">\n                <i class=\"fa-solid fa-circle-exclamation text-red-600 text-xl animate-pulse\"></i>\n                <span>ALERTA CRÍTICO: Clientes com Plano ATRASADO / VENCIDO!</span>\n              </h3>\n              <span id=\"alertExpiredCount\" class=\"bg-red-600 text-white font-extrabold text-xs px-3 py-1 rounded-full\">0 Clientes</span>\n            </div>\n            <div id=\"alertExpiredList\" class=\"space-y-2\">\n              <!-- Renderizado via JS -->\n            </div>\n          </div>\n        </div>\n\n        <!-- Connection Card & Quick Actions -->\n        <div class=\"grid grid-cols-1 lg:grid-cols-3 gap-6\">\n          <!-- WhatsApp Quick Status Card -->\n          <div class=\"bg-white border border-[#e2d7c5] rounded-2xl p-6 shadow-sm flex flex-col justify-between\">\n            <div>\n              <div class=\"flex items-center justify-between mb-4\">\n                <h3 class=\"font-extrabold text-lg text-slate-900 flex items-center gap-2\">\n                  <i class=\"fa-brands fa-whatsapp text-emerald-600 text-2xl\"></i>\n                  <span>Robô de Vendas</span>\n                </h3>\n                <span class=\"text-xs bg-emerald-100 text-emerald-800 font-bold px-3 py-1 rounded-full\">Ativo 24h</span>\n              </div>\n              <p class=\"text-sm text-slate-600 mb-6\">O robô responde automaticamente seus clientes no WhatsApp com base nos dados do seu prompt e realiza renovações em 1 clique.</p>\n\n              <div id=\"dashWaStatusBox\" class=\"bg-[#f7f3ea] p-5 rounded-xl border border-[#e2d7c5] text-center\">\n                <i id=\"dashWaIcon\" class=\"fa-solid fa-circle-check text-4xl text-emerald-600 mb-2\"></i>\n                <p id=\"dashWaText\" class=\"font-bold text-slate-800 text-base\">WhatsApp Conectado</p>\n              </div>\n            </div>\n\n            <div class=\"mt-6 pt-4 border-t border-slate-200\">\n              <button onclick=\"switchTab('whatsapp')\" class=\"w-full bg-brand-blue hover:bg-sky-700 text-white font-bold py-3 rounded-xl text-sm transition flex items-center justify-center space-x-2\">\n                <i class=\"fa-solid fa-qrcode\"></i>\n                <span>Ver QR Code / Conectar</span>\n              </button>\n            </div>\n          </div>\n\n          <!-- Quick Actions & Cloud Hosting Guide -->\n          <div class=\"lg:col-span-2 bg-white border border-[#e2d7c5] rounded-2xl p-6 shadow-sm flex flex-col justify-between\">\n            <div>\n              <h3 class=\"font-extrabold text-lg text-slate-900 mb-3 flex items-center gap-2\">\n                <i class=\"fa-solid fa-cloud text-brand-blue text-xl\"></i>\n                <span>Hospedagem Grátis 24 Horas na Nuvem</span>\n              </h3>\n              <p class=\"text-sm text-slate-600 mb-4 leading-relaxed\">\n                Para manter este sistema rodando <b>24 horas por dia</b> mesmo com seu computador desligado, você pode hospedá-lo gratuitamente no <b>Render.com</b> ou <b>Koyeb</b> + <b>UptimeRobot</b>.\n              </p>\n\n              <div class=\"grid grid-cols-1 sm:grid-cols-2 gap-4\">\n                <div class=\"bg-[#f7f3ea] p-4 rounded-xl border border-[#e2d7c5]\">\n                  <span class=\"font-extrabold text-brand-orange text-base block mb-1\">1. Render.com / Koyeb (Grátis)</span>\n                  <p class=\"text-xs text-slate-600\">Suba o código deste projeto para o GitHub e conecte ao Render para rodar o Node.js 24/7.</p>\n                </div>\n                <div class=\"bg-[#f7f3ea] p-4 rounded-xl border border-[#e2d7c5]\">\n                  <span class=\"font-extrabold text-brand-blue text-base block mb-1\">2. UptimeRobot (Grátis)</span>\n                  <p class=\"text-xs text-slate-600\">Configure um monitor HTTP grátis pingando a URL <code>/ping</code> a cada 5 minutos para evitar hibernação.</p>\n                </div>\n              </div>\n            </div>\n\n            <div class=\"mt-6 pt-4 border-t border-slate-200 flex justify-end\">\n              <button onclick=\"openClientModal()\" class=\"bg-gradient-to-r from-brand-orange to-brand-orangeDark hover:from-brand-orangeDark hover:to-orange-700 text-white font-bold px-6 py-3 rounded-xl text-sm shadow-md transition transform hover:scale-105\">\n                <i class=\"fa-solid fa-user-plus\"></i>\n                <span>Cadastrar Novo Cliente</span>\n              </button>\n            </div>\n          </div>\n        </div>\n      </section>\n\n      <!-- 2. TAB: CLIENTS (CRM) -->\n      <section id=\"tab-clients\" class=\"tab-content hidden space-y-6\">\n        <!-- Filter, Search and View Toggle Bar -->\n        <div class=\"bg-white border border-[#e2d7c5] p-5 rounded-2xl shadow-sm flex flex-col md:flex-row justify-between items-center gap-4\">\n          <div class=\"relative w-full md:w-80\">\n            <i class=\"fa-solid fa-magnifying-glass absolute left-3.5 top-3.5 text-slate-400 text-base\"></i>\n            <input type=\"text\" id=\"searchClientInput\" oninput=\"filterClients()\" placeholder=\"Buscar por código, nome, app ou servidor...\" class=\"w-full pl-10 pr-4 py-3 bg-white border border-slate-300 rounded-xl text-base text-slate-900 focus:outline-none focus:border-brand-blue\">\n          </div>\n\n          <div class=\"flex items-center space-x-3 w-full md:w-auto overflow-x-auto\">\n            <select id=\"filterStatusSelect\" onchange=\"filterClients()\" class=\"p-3 bg-white border border-slate-300 rounded-xl text-sm font-bold text-slate-800 focus:outline-none\">\n              <option value=\"all\">Todos os Status</option>\n              <option value=\"active\">🟢 Ativos</option>\n              <option value=\"expiring\">🟠 Próximos do Vencimento</option>\n              <option value=\"expired\">🔴 Vencidos</option>\n            </select>\n\n            <!-- Seletor de Modo de Visualização (Cards vs Tabela) -->\n            <div class=\"flex bg-[#efe8dc] p-1 rounded-xl border border-[#e2d7c5]\">\n              <button id=\"viewBtnCards\" onclick=\"setCrmViewMode('cards')\" class=\"px-4 py-2 rounded-lg text-sm font-bold transition bg-brand-blue text-white shadow-sm\">\n                <i class=\"fa-solid fa-id-card\"></i> Cards 🃏\n              </button>\n              <button id=\"viewBtnTable\" onclick=\"setCrmViewMode('table')\" class=\"px-4 py-2 rounded-lg text-sm font-bold text-slate-700 hover:text-slate-900 transition\">\n                <i class=\"fa-solid fa-table-list\"></i> Tabela 📊\n              </button>\n            </div>\n\n            <button onclick=\"openClientModal()\" class=\"bg-brand-orange hover:bg-orange-600 text-white text-sm px-5 py-3 rounded-xl font-bold transition flex items-center space-x-2 whitespace-nowrap shadow-sm\">\n              <i class=\"fa-solid fa-user-plus\"></i>\n              <span>Novo Cliente</span>\n            </button>\n          </div>\n        </div>\n\n        <!-- MODO CARDS (GRID DE CARDS INDIVIDUAL PARA CADA CLIENTE) -->\n        <div id=\"clientsCardsGrid\" class=\"grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-5\">\n          <!-- Cards gerados via JS -->\n        </div>\n\n        <!-- MODO TABELA (VISUALIZAÇÃO EM LISTA) -->\n        <div id=\"clientsTableView\" class=\"hidden bg-white border border-[#e2d7c5] rounded-2xl overflow-hidden shadow-sm\">\n          <div class=\"overflow-x-auto\">\n            <table class=\"w-full text-left text-base text-slate-800\">\n              <thead class=\"bg-[#f0e9dd] text-sm uppercase text-slate-700 font-extrabold border-b border-[#e2d7c5]\">\n                <tr>\n                  <th class=\"py-4 px-4\">Código</th>\n                  <th class=\"py-4 px-4\">Cliente</th>\n                  <th class=\"py-4 px-4\">WhatsApp</th>\n                  <th class=\"py-4 px-4\">Plano & Valor</th>\n                  <th class=\"py-4 px-4\">App & Servidor</th>\n                  <th class=\"py-4 px-4\">Vencimento (30d)</th>\n                  <th class=\"py-4 px-4\">Status</th>\n                  <th class=\"py-4 px-4 text-right\">Ações</th>\n                </tr>\n              </thead>\n              <tbody id=\"clientsTableBody\" class=\"divide-y divide-[#e2d7c5]\">\n                <!-- Linhas inseridas via JS -->\n              </tbody>\n            </table>\n          </div>\n        </div>\n      </section>\n\n      <!-- 2.1 TAB: CARDS DE PLANOS DE CANAIS COM CORES -->\n      <section id=\"tab-plans\" class=\"tab-content hidden space-y-6\">\n        <div class=\"bg-white border border-[#e2d7c5] rounded-2xl p-6 shadow-sm\">\n          <div class=\"flex items-center justify-between mb-6\">\n            <div class=\"flex items-center space-x-3\">\n              <div class=\"w-12 h-12 rounded-xl bg-sky-500/10 text-sky-600 flex items-center justify-center text-2xl font-bold\">\n                <i class=\"fa-solid fa-tv\"></i>\n              </div>\n              <div>\n                <h2 class=\"text-xl font-extrabold text-slate-900\">Cadastro de Cards de Planos de Canais</h2>\n                <p class=\"text-sm text-slate-600\">Cadastre os planos com cores personalizadas para cada card.</p>\n              </div>\n            </div>\n          </div>\n\n          <!-- Add Plan Form with Color Picker -->\n          <form id=\"addPlanForm\" onsubmit=\"saveNewPlan(event)\" class=\"bg-[#f7f3ea] p-5 rounded-2xl border border-[#e2d7c5] mb-6 space-y-4\">\n            <h3 class=\"text-base font-extrabold text-slate-900 flex items-center gap-2\">\n              <i class=\"fa-solid fa-palette text-brand-orange\"></i>\n              <span>Criar Novo Card de Plano Personalizado</span>\n            </h3>\n\n            <div class=\"grid grid-cols-1 md:grid-cols-4 gap-4\">\n              <div class=\"md:col-span-2\">\n                <label class=\"block text-xs font-bold text-slate-700 mb-1\">Nome do Plano *</label>\n                <input type=\"text\" id=\"newPlanName\" required placeholder=\"Ex: IPTV CLIENTES 1 Tela 4K\" class=\"w-full p-3 bg-white border border-slate-300 rounded-xl text-base text-slate-900 focus:outline-none font-medium\">\n              </div>\n\n              <div>\n                <label class=\"block text-xs font-bold text-slate-700 mb-1\">Valor Mensal (R$) *</label>\n                <input type=\"number\" step=\"0.01\" id=\"newPlanPrice\" required placeholder=\"35.00\" class=\"w-full p-3 bg-white border border-slate-300 rounded-xl text-base text-slate-900 focus:outline-none font-bold\">\n              </div>\n\n              <div>\n                <label class=\"block text-xs font-bold text-slate-700 mb-1\">Cor do Card *</label>\n                <select id=\"newPlanColor\" class=\"w-full p-3 bg-white border border-slate-300 rounded-xl text-base text-slate-900 font-bold focus:outline-none\">\n                  <option value=\"#0284c7\">🟦 Azul Claro Tecnológico</option>\n                  <option value=\"#f97316\">🟧 Laranja Brilhante</option>\n                  <option value=\"#10b981\">🟩 Verde Esmeralda</option>\n                  <option value=\"#8b5cf6\">🟪 Roxo Imperial</option>\n                  <option value=\"#f59e0b\">🟨 Amarelo Dourado</option>\n                  <option value=\"#f43f5e\">🟥 Rosa / Vermelho Vivo</option>\n                </select>\n              </div>\n            </div>\n\n            <div>\n              <label class=\"block text-xs font-bold text-slate-700 mb-1\">Descrição do Plano</label>\n              <input type=\"text\" id=\"newPlanDesc\" placeholder=\"Ex: Canais abertos/fechados + Filmes e Séries 4K + Futebol ao Vivo\" class=\"w-full p-3 bg-white border border-slate-300 rounded-xl text-base text-slate-900 focus:outline-none font-medium\">\n            </div>\n\n            <div class=\"flex justify-end\">\n              <button type=\"submit\" class=\"bg-brand-orange hover:bg-orange-600 text-white font-bold px-6 py-3 rounded-xl text-sm transition flex items-center space-x-2 shadow-sm\">\n                <i class=\"fa-solid fa-plus\"></i>\n                <span>Salvar Card de Plano</span>\n              </button>\n            </div>\n          </form>\n\n          <!-- Registered Colorful Plan Cards Grid -->\n          <h3 class=\"text-base font-extrabold text-slate-900 mb-4\">Cards de Planos Ativos no Sistema</h3>\n          <div id=\"plansGrid\" class=\"grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6\">\n            <!-- Cards de planos gerados via JS -->\n          </div>\n        </div>\n      </section>\n\n      <!-- 2.2 TAB: APPS & SERVIDORES IPTV -->\n      <section id=\"tab-apps_servers\" class=\"tab-content hidden space-y-6\">\n        <div class=\"grid grid-cols-1 lg:grid-cols-2 gap-6\">\n          <!-- GERENCIADOR DE APLICATIVOS -->\n          <div class=\"bg-white border border-[#e2d7c5] rounded-2xl p-6 shadow-sm\">\n            <div class=\"flex items-center space-x-3 mb-6\">\n              <div class=\"w-12 h-12 rounded-xl bg-purple-500/10 text-purple-600 flex items-center justify-center text-2xl font-bold\">\n                <i class=\"fa-solid fa-mobile-screen-button\"></i>\n              </div>\n              <div>\n                <h2 class=\"text-xl font-extrabold text-slate-900\">Aplicativos IPTV</h2>\n                <p class=\"text-sm text-slate-600\">Cadastre os apps usados pelos seus clientes.</p>\n              </div>\n            </div>\n\n            <form id=\"addAppForm\" onsubmit=\"saveNewApp(event)\" class=\"bg-[#f7f3ea] p-4 rounded-xl border border-[#e2d7c5] mb-5 space-y-3\">\n              <div>\n                <label class=\"block text-xs font-bold text-slate-700 mb-1\">Nome do Aplicativo *</label>\n                <input type=\"text\" id=\"newAppName\" required placeholder=\"Ex: XCIPTV Player, IBO Player\" class=\"w-full p-3 bg-white border border-slate-300 rounded-xl text-base text-slate-900 font-medium\">\n              </div>\n              <div class=\"flex justify-end\">\n                <button type=\"submit\" class=\"bg-purple-600 hover:bg-purple-700 text-white font-bold px-5 py-2.5 rounded-xl text-sm transition shadow-sm\">\n                  <i class=\"fa-solid fa-plus\"></i> Cadastrar App\n                </button>\n              </div>\n            </form>\n\n            <div id=\"appsList\" class=\"space-y-2\">\n              <!-- Lista de Apps via JS -->\n            </div>\n          </div>\n\n          <!-- GERENCIADOR DE SERVIDORES -->\n          <div class=\"bg-white border border-[#e2d7c5] rounded-2xl p-6 shadow-sm\">\n            <div class=\"flex items-center space-x-3 mb-6\">\n              <div class=\"w-12 h-12 rounded-xl bg-brand-blue/10 text-brand-blue flex items-center justify-center text-2xl font-bold\">\n                <i class=\"fa-solid fa-server\"></i>\n              </div>\n              <div>\n                <h2 class=\"text-xl font-extrabold text-slate-900\">Servidores IPTV</h2>\n                <p class=\"text-sm text-slate-600\">Cadastre os servidores que sua empresa utiliza.</p>\n              </div>\n            </div>\n\n            <form id=\"addServerForm\" onsubmit=\"saveNewServer(event)\" class=\"bg-[#f7f3ea] p-4 rounded-xl border border-[#e2d7c5] mb-5 space-y-3\">\n              <div>\n                <label class=\"block text-xs font-bold text-slate-700 mb-1\">Nome do Servidor *</label>\n                <input type=\"text\" id=\"newServerName\" required placeholder=\"Ex: Servidor Premium Gold, Servidor Star\" class=\"w-full p-3 bg-white border border-slate-300 rounded-xl text-base text-slate-900 font-medium\">\n              </div>\n              <div class=\"flex justify-end\">\n                <button type=\"submit\" class=\"bg-brand-blue hover:bg-sky-700 text-white font-bold px-5 py-2.5 rounded-xl text-sm transition shadow-sm\">\n                  <i class=\"fa-solid fa-plus\"></i> Cadastrar Servidor\n                </button>\n              </div>\n            </form>\n\n            <div id=\"serversList\" class=\"space-y-2\">\n              <!-- Lista de Servidores via JS -->\n            </div>\n          </div>\n        </div>\n      </section>\n\n      <!-- 3. TAB: CONNECT WHATSAPP -->\n      <section id=\"tab-whatsapp\" class=\"tab-content hidden space-y-6\">\n        <div class=\"bg-white border border-[#e2d7c5] rounded-2xl p-8 text-center max-w-xl mx-auto shadow-sm\">\n          <div class=\"w-20 h-20 bg-emerald-500/10 text-emerald-600 rounded-full flex items-center justify-center text-4xl mx-auto mb-4 border border-emerald-500/20\">\n            <i class=\"fa-brands fa-whatsapp\"></i>\n          </div>\n\n          <h2 class=\"text-2xl font-extrabold text-slate-900 mb-2\">Conectar WhatsApp (Normal ou Business)</h2>\n          <p class=\"text-sm text-slate-600 mb-6\">Abra o WhatsApp no seu celular, vá em <b class=\"text-slate-800\">Aparelhos Conectados &rarr; Conectar um Aparelho</b> e aponte a câmera para o QR Code abaixo.</p>\n\n          <!-- QR Code View Box -->\n          <div id=\"qrCodeContainer\" class=\"bg-white p-5 rounded-2xl inline-block shadow-xl border-4 border-brand-blue min-w-[260px] min-h-[260px] flex items-center justify-center relative\">\n            <div id=\"qrLoadingSpinner\" class=\"flex flex-col items-center space-y-3 text-slate-700\">\n              <i class=\"fa-solid fa-circle-notch fa-spin text-5xl text-brand-blue\"></i>\n              <span class=\"text-sm font-bold\">Gerando QR Code...</span>\n            </div>\n            <img id=\"qrCodeImg\" class=\"hidden max-w-[240px] max-h-[240px] rounded-lg\" alt=\"QR Code WhatsApp\">\n          </div>\n\n          <!-- Status Message -->\n          <div id=\"waConnectStatusText\" class=\"mt-5 text-base font-bold text-slate-800\">\n            Aguardando escaneamento...\n          </div>\n\n          <div class=\"mt-6 flex justify-center space-x-3\">\n            <button onclick=\"reconnectWhatsApp()\" class=\"bg-brand-blue hover:bg-sky-700 text-white px-6 py-3 rounded-xl font-bold text-sm transition flex items-center space-x-2 shadow-sm\">\n              <i class=\"fa-solid fa-arrows-rotate\"></i>\n              <span>Gerar Novo QR Code</span>\n            </button>\n          </div>\n        </div>\n      </section>\n\n      <!-- 4. TAB: AI & PROMPT SETTINGS -->\n      <section id=\"tab-ai_prompt\" class=\"tab-content hidden space-y-6\">\n        <div class=\"bg-white border border-[#e2d7c5] rounded-2xl p-6 shadow-sm\">\n          <div class=\"flex items-center space-x-3 mb-6\">\n            <div class=\"w-12 h-12 rounded-xl bg-brand-blue/10 text-brand-blue flex items-center justify-center text-2xl font-bold\">\n              <i class=\"fa-solid fa-robot\"></i>\n            </div>\n            <div>\n              <h2 class=\"text-xl font-extrabold text-slate-900\">Inteligência Artificial & Prompt do Sistema</h2>\n              <p class=\"text-sm text-slate-600\">Configure as regras de atendimento para a IA responder seus clientes automaticamente.</p>\n            </div>\n          </div>\n\n          <form id=\"aiPromptForm\" onsubmit=\"saveAiSettings(event)\" class=\"space-y-6\">\n            <div>\n              <label class=\"block text-sm font-bold text-slate-800 mb-1.5\">Chave API Google Gemini (Gratuito - Opcional)</label>\n              <input type=\"password\" id=\"geminiApiKey\" placeholder=\"Cole sua API Key do Google AI Studio (ou deixe em branco para usar o motor grátis)\" class=\"w-full p-3.5 bg-white border border-slate-300 rounded-xl text-base focus:outline-none focus:border-brand-blue text-slate-900 font-medium\">\n              <p class=\"text-xs text-slate-500 mt-1\">Se não preencher, o sistema usará o Motor de Regras Inteligente totalmente gratuito sem limites.</p>\n            </div>\n\n            <div>\n              <label class=\"block text-sm font-bold text-slate-800 mb-1.5\">Prompt Personalizado Geral do Sistema (Instruções da sua Empresa)</label>\n              <textarea id=\"systemPromptText\" rows=\"10\" class=\"w-full p-4 bg-white border border-slate-300 rounded-xl text-base focus:outline-none focus:border-brand-blue text-slate-900 font-mono leading-relaxed\" placeholder=\"Escreva aqui as regras do robô...\"></textarea>\n              <p class=\"text-xs text-brand-blue font-bold mt-1\">✨ A IA e o sistema usam esse texto para responder dúvidas sobre preços, suporte, testes e regras dos canais.</p>\n            </div>\n\n            <!-- Caixa de Adição Rápida de Informações ao Prompt -->\n            <div class=\"bg-[#f7f3ea] p-5 rounded-xl border border-[#e2d7c5] space-y-3\">\n              <label class=\"block text-sm font-extrabold text-brand-orange uppercase tracking-wider flex items-center gap-2\">\n                <i class=\"fa-solid fa-plus-circle text-lg\"></i>\n                <span>Adicionar Nova Informação / Regra ao Prompt Geral</span>\n              </label>\n              <div class=\"flex flex-col sm:flex-row gap-3\">\n                <input type=\"text\" id=\"quickPromptInfoInput\" placeholder=\"Ex: Promoção de Setembro: Plano Anual por R$ 250 no Pix\" class=\"flex-1 p-3 bg-white border border-slate-300 rounded-xl text-base text-slate-900 focus:outline-none focus:border-brand-orange font-medium\">\n                <button type=\"button\" onclick=\"appendQuickInfoToPrompt()\" class=\"bg-gradient-to-r from-brand-orange to-brand-orangeDark hover:from-brand-orangeDark hover:to-orange-700 text-white font-bold px-6 py-3 rounded-xl text-sm whitespace-nowrap transition flex items-center space-x-2 shadow-sm\">\n                  <i class=\"fa-solid fa-plus\"></i>\n                  <span>Anexar ao Prompt</span>\n                </button>\n              </div>\n              <p class=\"text-xs text-slate-600\">Esta informação será anexada ao Prompt Geral do sistema imediatamente e salva no banco de dados.</p>\n            </div>\n\n            <div class=\"grid grid-cols-1 md:grid-cols-2 gap-5\">\n              <div>\n                <label class=\"block text-sm font-bold text-slate-800 mb-1.5\">Duração do Teste Grátis</label>\n                <input type=\"text\" id=\"testDuration\" placeholder=\"ex: 2 horas, 4 horas\" class=\"w-full p-3.5 bg-white border border-slate-300 rounded-xl text-base focus:outline-none focus:border-brand-blue text-slate-900 font-medium\">\n              </div>\n\n              <div>\n                <label class=\"block text-sm font-bold text-slate-800 mb-1.5\">Chave PIX para Renovação (Salva e Preserva Seus Dados)</label>\n                <input type=\"text\" id=\"pixKeyInput\" placeholder=\"Ex: 11985897774 ou Banco CELCOIN - Gerailton Neves - Pix 11985897774\" class=\"w-full p-3.5 bg-white border border-slate-300 rounded-xl text-base focus:outline-none focus:border-brand-blue text-slate-900 font-medium\">\n              </div>\n\n              <!-- UPLOAD DE LOGO DA EMPRESA -->\n              <div class=\"bg-[#f7f3ea] p-5 rounded-2xl border border-[#e2d7c5] space-y-4\">\n                <label class=\"block text-sm font-extrabold text-slate-800 flex items-center gap-2\">\n                  <i class=\"fa-solid fa-image text-brand-orange text-lg\"></i>\n                  <span>Logo da Empresa (Para Recibos Profissionais)</span>\n                </label>\n                \n                <div class=\"flex flex-col sm:flex-row items-center gap-4\">\n                  <!-- Preview Box -->\n                  <div id=\"logoPreviewBox\" class=\"min-w-[100px] max-w-[220px] h-24 p-1 rounded-2xl bg-white border-2 border-dashed border-slate-300 flex items-center justify-center overflow-hidden relative shadow-sm shrink-0\">\n                    <i id=\"logoPreviewIcon\" class=\"fa-solid fa-cloud-arrow-up text-3xl text-slate-400\"></i>\n                    <img id=\"logoPreviewImg\" class=\"hidden max-h-20 w-auto object-contain p-1\" alt=\"Logo da Empresa\">\n                  </div>\n\n                  <!-- Upload Controls -->\n                  <div class=\"flex-1 space-y-2 text-center sm:text-left\">\n                    <input type=\"file\" id=\"logoFileInput\" accept=\"image/*\" onchange=\"uploadLogoFile(event)\" class=\"hidden\">\n                    <input type=\"hidden\" id=\"companyLogoInput\">\n                    \n                    <div class=\"flex flex-wrap gap-2 justify-center sm:justify-start\">\n                      <button type=\"button\" onclick=\"document.getElementById('logoFileInput').click()\" class=\"bg-brand-blue hover:bg-sky-700 text-white font-bold px-4 py-2.5 rounded-xl text-sm transition flex items-center space-x-2 shadow-sm\">\n                        <i class=\"fa-solid fa-upload\"></i>\n                        <span>Fazer Upload da Foto da Logo</span>\n                      </button>\n                      <button type=\"button\" onclick=\"removeLogoFile()\" class=\"bg-red-100 hover:bg-red-200 text-red-700 font-bold px-3 py-2.5 rounded-xl text-sm transition flex items-center space-x-1 border border-red-300\">\n                        <i class=\"fa-solid fa-trash\"></i>\n                        <span>Remover</span>\n                      </button>\n                    </div>\n                    <p class=\"text-xs text-slate-600 font-medium\">Selecione uma foto da sua marca do computador ou celular (PNG, JPG, WEBP). Ela aparecerá estampada nos recibos!</p>\n                  </div>\n                </div>\n              </div>\n            </div>\n\n            <div class=\"pt-2 flex justify-end\">\n              <button type=\"submit\" class=\"bg-brand-orange hover:bg-orange-600 text-white font-bold px-7 py-3 rounded-xl text-base transition flex items-center space-x-2 shadow-sm\">\n                <i class=\"fa-solid fa-floppy-disk\"></i>\n                <span>Salvar Configurações de IA</span>\n              </button>\n            </div>\n          </form>\n        </div>\n      </section>\n\n      <!-- 5. TAB: INTERACTIVE MENU -->\n      <section id=\"tab-interactive_menu\" class=\"tab-content hidden space-y-6\">\n        <div class=\"bg-white border border-[#e2d7c5] rounded-2xl p-6 shadow-sm\">\n          <h2 class=\"text-xl font-extrabold text-slate-900 mb-2 flex items-center gap-2\">\n            <i class=\"fa-solid fa-list-check text-purple-600\"></i>\n            <span>Menu Interativo de Autoatendimento</span>\n          </h2>\n          <p class=\"text-sm text-slate-600 mb-6\">Este é o menu automático enviado aos clientes na primeira mensagem ou quando enviam \"Menu\".</p>\n\n          <div class=\"grid grid-cols-1 lg:grid-cols-2 gap-6\">\n            <!-- Menu Preview Box -->\n            <div class=\"bg-[#f7f3ea] p-5 rounded-2xl border border-[#e2d7c5]\">\n              <h3 class=\"text-sm font-extrabold text-slate-700 uppercase tracking-wider mb-3\">Pré-visualização da Mensagem no WhatsApp</h3>\n              <div id=\"menuPreviewBox\" class=\"bg-white p-5 rounded-xl border border-slate-300 text-slate-900 font-mono text-sm whitespace-pre-wrap leading-relaxed shadow-inner\">\n                <!-- Preview carregado via JS -->\n              </div>\n            </div>\n\n            <!-- Options Description -->\n            <div class=\"space-y-4 text-base\">\n              <div class=\"bg-[#f7f3ea] p-4 rounded-xl border border-[#e2d7c5]\">\n                <span class=\"font-bold text-slate-900 block mb-1\">1️⃣ Consultar Vencimento & Pix</span>\n                <p class=\"text-xs text-slate-600\">Retorna o plano, valor, data de vencimento e chave Pix cadastrada no sistema.</p>\n              </div>\n\n              <div class=\"bg-[#f7f3ea] p-4 rounded-xl border border-[#e2d7c5]\">\n                <span class=\"font-bold text-slate-900 block mb-1\">2️⃣ Solicitar Teste Grátis</span>\n                <p class=\"text-xs text-slate-600\">Envia a mensagem solicitando o modelo de aparelho para geração de acesso temporário.</p>\n              </div>\n\n              <div class=\"bg-[#f7f3ea] p-4 rounded-xl border border-[#e2d7c5]\">\n                <span class=\"font-bold text-slate-900 block mb-1\">3️⃣ Ver Planos e Preços</span>\n                <p class=\"text-xs text-slate-600\">Envia a tabela completa dos planos Mensal, Trimestral e Anual.</p>\n              </div>\n\n              <div class=\"bg-[#f7f3ea] p-4 rounded-xl border border-[#e2d7c5]\">\n                <span class=\"font-bold text-slate-900 block mb-1\">4️⃣ Tirar Dúvidas com Atendente (IA)</span>\n                <p class=\"text-xs text-slate-600\">Aciona a Inteligência Artificial para responder qualquer dúvida usando o Prompt do Sistema.</p>\n              </div>\n            </div>\n          </div>\n        </div>\n      </section>\n\n      <!-- 6. TAB: RECEIPTS & BROADCAST -->\n      <section id=\"tab-receipts\" class=\"tab-content hidden space-y-6\">\n        <div class=\"bg-white border border-[#e2d7c5] rounded-2xl p-6 shadow-sm\">\n          <div class=\"flex items-center space-x-3 mb-6\">\n            <div class=\"w-12 h-12 rounded-xl bg-amber-500/10 text-amber-600 flex items-center justify-center text-2xl font-bold\">\n              <i class=\"fa-solid fa-receipt\"></i>\n            </div>\n            <div>\n              <h2 class=\"text-xl font-extrabold text-slate-900\">Gerador de Recibos & Disparo de Promoções</h2>\n              <p class=\"text-sm text-slate-600\">Histórico de renovações com código de recibo e envio de mensagens para clientes.</p>\n            </div>\n          </div>\n\n          <!-- Broadcast Message Box -->\n          <div class=\"bg-[#f7f3ea] p-5 rounded-2xl border border-[#e2d7c5] mb-6 space-y-4\">\n            <h3 class=\"text-base font-extrabold text-slate-900 flex items-center gap-2\">\n              <i class=\"fa-solid fa-paper-plane text-brand-orange\"></i>\n              <span>Enviar Mensagem de Promoção ou Aviso em Massa</span>\n            </h3>\n\n            <div>\n              <label class=\"block text-xs font-bold text-slate-700 mb-1\">Público Alvo</label>\n              <select id=\"broadcastTargetSelect\" class=\"w-full p-3 bg-white border border-slate-300 rounded-xl text-base font-medium text-slate-900 focus:outline-none\">\n                <option value=\"expiring\">🟠 Apenas Clientes Próximos do Vencimento (3 dias)</option>\n                <option value=\"expired\">🔴 Apenas Clientes com Plano Vencido</option>\n                <option value=\"all\">🟢 Todos os Clientes Cadastrados</option>\n              </select>\n            </div>\n\n            <div>\n              <label class=\"block text-xs font-bold text-slate-700 mb-1\">Mensagem da Promoção / Aviso</label>\n              <textarea id=\"broadcastMessageText\" rows=\"3\" class=\"w-full p-3 bg-white border border-slate-300 rounded-xl text-base text-slate-900 focus:outline-none\" placeholder=\"Digite a mensagem promocional ou lembrete...\"></textarea>\n            </div>\n\n            <div class=\"flex justify-end\">\n              <button onclick=\"sendBroadcastMessage()\" class=\"bg-brand-orange hover:bg-orange-600 text-white font-bold px-6 py-3 rounded-xl text-sm transition flex items-center space-x-2 shadow-sm\">\n                <i class=\"fa-solid fa-paper-plane\"></i>\n                <span>Enviar Notificação aos Clientes</span>\n              </button>\n            </div>\n          </div>\n\n          <!-- Receipts History Table -->\n          <div class=\"flex flex-col sm:flex-row items-start sm:items-center justify-between gap-3 mb-3\">\n            <div>\n              <h3 class=\"text-base font-extrabold text-slate-900 flex items-center gap-2\">\n                <i class=\"fa-solid fa-clock-rotate-left text-amber-600 text-lg\"></i>\n                <span>Histórico de Recibos de Renovação</span>\n              </h3>\n              <p class=\"text-xs text-slate-600 font-medium\">Você tem acesso completo para <b>Ver</b>, <b>Editar</b>, <b>Excluir</b> ou <b>Reenviar no WhatsApp</b> cada recibo.</p>\n            </div>\n            <button onclick=\"loadReceipts()\" class=\"bg-amber-100 hover:bg-amber-200 text-amber-900 font-bold px-3.5 py-2 rounded-xl text-xs transition border border-amber-300 flex items-center space-x-1.5 shadow-sm whitespace-nowrap\">\n              <i class=\"fa-solid fa-arrows-rotate\"></i>\n              <span>Atualizar Recibos</span>\n            </button>\n          </div>\n\n          <div class=\"overflow-x-auto border border-[#e2d7c5] rounded-xl shadow-sm\">\n            <table class=\"w-full text-left text-base text-slate-800\">\n              <thead class=\"bg-[#f0e9dd] text-sm uppercase text-slate-700 font-extrabold\">\n                <tr>\n                  <th class=\"py-3.5 px-4\">Código Recibo</th>\n                  <th class=\"py-3.5 px-4\">Cliente</th>\n                  <th class=\"py-3.5 px-4\">Plano</th>\n                  <th class=\"py-3.5 px-4\">Valor</th>\n                  <th class=\"py-3.5 px-4\">Data Renovação</th>\n                  <th class=\"py-3.5 px-4\">Próximo Vencimento</th>\n                  <th class=\"py-3.5 px-4 text-right\">Ação</th>\n                </tr>\n              </thead>\n              <tbody id=\"receiptsTableBody\" class=\"divide-y divide-[#e2d7c5]\">\n                <!-- Recibos inseridos via JS -->\n              </tbody>\n            </table>\n          </div>\n        </div>\n      </section>\n\n      <!-- 7. TAB: COMPANY SETTINGS -->\n      <section id=\"tab-settings\" class=\"tab-content hidden space-y-6\">\n        <div class=\"bg-white border border-[#e2d7c5] rounded-2xl p-6 shadow-sm\">\n          <div class=\"flex items-center space-x-3 mb-6\">\n            <div class=\"w-12 h-12 rounded-xl bg-slate-200 text-slate-700 flex items-center justify-center text-2xl font-bold\">\n              <i class=\"fa-solid fa-sliders\"></i>\n            </div>\n            <div>\n              <h2 class=\"text-xl font-extrabold text-slate-900\">Configurações Gerais da Empresa</h2>\n              <p class=\"text-sm text-slate-600\">Personalize o nome da sua empresa e chave PIX exibidos no sistema.</p>\n            </div>\n          </div>\n\n          <form id=\"companySettingsForm\" onsubmit=\"saveCompanySettings(event)\" class=\"space-y-5\">\n            <div>\n              <label class=\"block text-sm font-bold text-slate-800 mb-1.5\">Nome da Sua Empresa</label>\n              <input type=\"text\" id=\"companyNameInput\" placeholder=\"Ex: IPTV CLIENTES Brasil\" class=\"w-full p-3.5 bg-white border border-slate-300 rounded-xl text-base focus:outline-none focus:border-brand-blue text-slate-900 font-medium\">\n              <p class=\"text-xs text-slate-500 mt-1\">Este nome será exibido nas saudações e no recibo gerado aos clientes.</p>\n            </div>\n\n            <div>\n              <label class=\"block text-sm font-bold text-slate-800 mb-1.5\">Ativar Robô de Resposta Automática</label>\n              <select id=\"botEnabledSelect\" class=\"w-full p-3.5 bg-white border border-slate-300 rounded-xl text-base font-medium text-slate-900 focus:outline-none\">\n                <option value=\"true\">🟢 Sim - Ativado (Robô responde automático no WhatsApp 24h)</option>\n                <option value=\"false\">🔴 Não - Desativado (Apenas gestão manual de clientes)</option>\n              </select>\n            </div>\n\n            <div class=\"pt-2 flex justify-end\">\n              <button type=\"submit\" class=\"bg-brand-blue hover:bg-sky-700 text-white font-bold px-7 py-3 rounded-xl text-base transition flex items-center space-x-2 shadow-sm\">\n                <i class=\"fa-solid fa-floppy-disk\"></i>\n                <span>Salvar Dados da Empresa</span>\n              </button>\n            </div>\n          </form>\n        </div>\n      </section>\n\n    </main>\n  </div>\n\n  <!-- MODAL: CADASTRAR / EDITAR CLIENTE -->\n  <div id=\"clientModal\" class=\"fixed inset-0 bg-slate-900/60 backdrop-blur-sm z-50 hidden flex items-center justify-center p-4\">\n    <div class=\"bg-white border border-[#e2d7c5] rounded-3xl max-w-lg w-full p-7 shadow-2xl animate-fade-in relative max-h-[90vh] overflow-y-auto\">\n      <div class=\"flex justify-between items-center mb-6\">\n        <h3 id=\"clientModalTitle\" class=\"text-xl font-extrabold text-slate-900\">Cadastrar Novo Cliente</h3>\n        <button onclick=\"closeClientModal()\" class=\"text-slate-400 hover:text-slate-700 text-2xl font-bold\">&times;</button>\n      </div>\n\n      <form id=\"clientForm\" onsubmit=\"saveClient(event)\" class=\"space-y-4\">\n        <input type=\"hidden\" id=\"clientId\">\n\n        <div>\n          <label class=\"block text-sm font-bold text-slate-800 mb-1\">Nome Completo do Cliente *</label>\n          <input type=\"text\" id=\"clientName\" required placeholder=\"Ex: João da Silva\" class=\"w-full p-3.5 bg-white border border-slate-300 rounded-xl text-base text-slate-900 focus:outline-none focus:border-brand-blue font-medium\">\n        </div>\n\n        <div>\n          <label class=\"block text-sm font-bold text-slate-800 mb-1\">Número do WhatsApp * (DDD + Número)</label>\n          <input type=\"text\" id=\"clientPhone\" required placeholder=\"Ex: 11985897774 (Sem colocar o 55 na frente)\" class=\"w-full p-3.5 bg-white border border-slate-300 rounded-xl text-base text-slate-900 focus:outline-none focus:border-brand-blue font-medium\">\n        </div>\n\n        <div>\n          <label class=\"block text-sm font-bold text-slate-800 mb-1\">Selecione o Plano de Canais</label>\n          <select id=\"clientPlanSelect\" onchange=\"onClientPlanSelectChange()\" class=\"w-full p-3.5 bg-white border border-slate-300 rounded-xl text-base text-slate-900 font-bold focus:outline-none\">\n            <!-- Opções inseridas via JS -->\n          </select>\n        </div>\n\n        <div class=\"grid grid-cols-2 gap-3\">\n          <div>\n            <label class=\"block text-sm font-bold text-slate-800 mb-1\">Nome do Plano</label>\n            <input type=\"text\" id=\"clientPlanName\" placeholder=\"Ex: IPTV CLIENTES 1 Tela\" class=\"w-full p-3.5 bg-white border border-slate-300 rounded-xl text-base text-slate-900 focus:outline-none font-medium\">\n          </div>\n\n          <div>\n            <label class=\"block text-sm font-bold text-slate-800 mb-1\">Valor Mensal (R$)</label>\n            <input type=\"number\" step=\"0.01\" id=\"clientPrice\" placeholder=\"35.00\" class=\"w-full p-3.5 bg-white border border-slate-300 rounded-xl text-base text-slate-900 focus:outline-none font-bold\">\n          </div>\n        </div>\n\n        <div class=\"grid grid-cols-2 gap-3\">\n          <div>\n            <label class=\"block text-sm font-bold text-slate-800 mb-1\">📱 Aplicativo Usado</label>\n            <select id=\"clientAppSelect\" class=\"w-full p-3.5 bg-white border border-slate-300 rounded-xl text-base text-slate-900 font-medium focus:outline-none\">\n              <!-- Opções de Apps via JS -->\n            </select>\n          </div>\n\n          <div>\n            <label class=\"block text-sm font-bold text-slate-800 mb-1\">🖥 Servidor Usado</label>\n            <select id=\"clientServerSelect\" class=\"w-full p-3.5 bg-white border border-slate-300 rounded-xl text-base text-slate-900 font-medium focus:outline-none\">\n              <!-- Opções de Servidores via JS -->\n            </select>\n          </div>\n        </div>\n\n        <div class=\"grid grid-cols-2 gap-3\">\n          <div>\n            <label class=\"block text-sm font-bold text-slate-800 mb-1\">Vencimento *</label>\n            <input type=\"date\" id=\"clientDueDate\" required class=\"w-full p-3.5 bg-white border border-slate-300 rounded-xl text-base text-slate-900 focus:outline-none font-medium\">\n          </div>\n\n          <div>\n            <label class=\"block text-sm font-bold text-slate-800 mb-1\">Status do Plano</label>\n            <select id=\"clientStatus\" class=\"w-full p-3.5 bg-white border border-slate-300 rounded-xl text-base text-slate-900 font-bold focus:outline-none\">\n              <option value=\"active\">🟢 Ativo</option>\n              <option value=\"expiring\">🟠 Próx. Vencimento</option>\n              <option value=\"expired\">🔴 Vencido / Suspenso</option>\n            </select>\n          </div>\n        </div>\n\n        <div>\n          <label class=\"block text-sm font-bold text-slate-800 mb-1\">Observações / Código Personalizado</label>\n          <input type=\"text\" id=\"clientNotes\" placeholder=\"Ex: CÓDIGO PROMPT: #812600\" class=\"w-full p-3.5 bg-white border border-slate-300 rounded-xl text-base text-slate-900 focus:outline-none font-medium\">\n        </div>\n\n        <div class=\"pt-4 flex justify-end space-x-3\">\n          <button type=\"button\" onclick=\"closeClientModal()\" class=\"px-5 py-3 rounded-xl border border-slate-300 text-slate-700 font-bold text-sm hover:bg-slate-100 transition\">Cancelar</button>\n          <button type=\"submit\" class=\"bg-brand-orange hover:bg-orange-600 text-white font-bold px-6 py-3 rounded-xl text-sm transition shadow-sm\">Salvar Cliente</button>\n        </div>\n      </form>\n    </div>\n  </div>\n\n  <!-- MODAL: RECIBO DE RENOVAÇÃO PROFISSIONAL -->\n  <div id=\"receiptModal\" style=\"display: none;\" class=\"fixed inset-0 bg-slate-900/60 backdrop-blur-sm z-50 flex items-center justify-center p-4\">\n    <div class=\"bg-white border border-[#e2d7c5] rounded-3xl max-w-lg w-full p-6 shadow-2xl animate-fade-in relative space-y-4 max-h-[90vh] overflow-y-auto\">\n      <div class=\"flex justify-between items-center pb-3 border-b border-slate-200\">\n        <h3 class=\"text-xl font-extrabold text-slate-900 flex items-center gap-2\">\n          <i class=\"fa-solid fa-receipt text-amber-600 text-2xl\"></i>\n          <span>Recibo de Renovação</span>\n        </h3>\n        <button onclick=\"closeReceiptModal()\" class=\"text-slate-400 hover:text-slate-700 text-2xl font-bold\">&times;</button>\n      </div>\n\n      <!-- VISUAL RECEIPT CARD (PROFISSIONAL COM LOGO) -->\n      <div id=\"receiptVisualCard\" class=\"bg-gradient-to-b from-slate-900 to-slate-800 text-white rounded-2xl p-6 shadow-lg border border-slate-700 relative overflow-hidden\">\n        <!-- Logo & Header -->\n        <div class=\"flex items-center justify-between border-b border-slate-700 pb-4 mb-4\">\n          <div class=\"flex items-center space-x-3\">\n            <div id=\"receiptLogoBox\" class=\"w-12 h-12 rounded-xl bg-white/10 flex items-center justify-center overflow-hidden border border-white/20\">\n              <i class=\"fa-solid fa-tv text-amber-400 text-2xl\"></i>\n            </div>\n            <div>\n              <h4 id=\"receiptCompanyName\" class=\"font-extrabold text-lg tracking-wide text-white\">GN IPTV</h4>\n              <span class=\"text-xs text-amber-400 font-bold uppercase tracking-wider\">Comprovante Oficial de Renovação</span>\n            </div>\n          </div>\n          <span id=\"receiptCodeBadge\" class=\"bg-amber-500/20 text-amber-300 border border-amber-500/40 font-mono font-extrabold text-xs px-3 py-1.5 rounded-lg shadow-sm\">\n            REC-000000\n          </span>\n        </div>\n\n        <!-- Details Grid -->\n        <div class=\"space-y-3 text-sm\">\n          <div class=\"flex justify-between border-b border-slate-700/60 pb-2\">\n            <span class=\"text-slate-400\">Cliente:</span>\n            <span id=\"receiptClientNameText\" class=\"font-bold text-white\">Nome do Cliente</span>\n          </div>\n\n          <div class=\"flex justify-between border-b border-slate-700/60 pb-2\">\n            <span class=\"text-slate-400\">Plano Contratado:</span>\n            <span id=\"receiptPlanNameText\" class=\"font-bold text-amber-300\">IPTV CLIENTES 1 Tela</span>\n          </div>\n\n          <div class=\"flex justify-between border-b border-slate-700/60 pb-2\">\n            <span class=\"text-slate-400\">Valor Pago:</span>\n            <span id=\"receiptPriceText\" class=\"font-extrabold text-emerald-400 text-base\">R$ 35,00</span>\n          </div>\n\n          <div class=\"flex justify-between border-b border-slate-700/60 pb-2\">\n            <span class=\"text-slate-400\">Data do Pagamento:</span>\n            <span id=\"receiptDateText\" class=\"font-bold text-slate-200\">DD/MM/AAAA</span>\n          </div>\n\n          <div class=\"flex justify-between bg-emerald-500/10 p-3 rounded-xl border border-emerald-500/30\">\n            <span class=\"text-emerald-300 font-bold flex items-center gap-1.5\">\n              <i class=\"fa-solid fa-calendar-check\"></i> Próximo Vencimento:\n            </span>\n            <span id=\"receiptNextDueText\" class=\"font-extrabold text-emerald-300 text-base\">DD/MM/AAAA</span>\n          </div>\n        </div>\n\n        <div class=\"mt-4 pt-3 border-t border-slate-700/60 text-center text-xs text-slate-400 italic\">\n          Obrigado pela preferência! Desejamos um ótimo entretenimento! 🍿📺\n        </div>\n      </div>\n\n      <!-- TEXT AREA FORMAT (PARA WHATSAPP) -->\n      <div class=\"bg-[#f7f3ea] p-3.5 rounded-xl border border-[#e2d7c5]\">\n        <label class=\"block text-xs font-bold text-slate-700 mb-1\">Texto Formatado para WhatsApp:</label>\n        <div id=\"receiptBoxContent\" class=\"bg-white p-3 rounded-xl border border-slate-300 font-mono text-xs text-slate-900 whitespace-pre-wrap leading-relaxed max-h-36 overflow-y-auto\">\n          <!-- Conteúdo do recibo em texto gerado via JS -->\n        </div>\n      </div>\n\n      <!-- ACTION BUTTONS -->\n      <div class=\"grid grid-cols-2 sm:grid-cols-4 gap-2 pt-1\">\n        <button onclick=\"copyReceiptText()\" class=\"bg-slate-800 hover:bg-slate-900 text-white font-bold py-2.5 px-3 rounded-xl text-xs transition flex items-center justify-center space-x-1.5 shadow-sm\">\n          <i class=\"fa-solid fa-copy\"></i>\n          <span>Copiar</span>\n        </button>\n        <button onclick=\"sendReceiptViaWhatsapp()\" class=\"bg-emerald-600 hover:bg-emerald-700 text-white font-bold py-2.5 px-3 rounded-xl text-xs transition flex items-center justify-center space-x-1.5 shadow-sm\">\n          <i class=\"fa-brands fa-whatsapp\"></i>\n          <span>WhatsApp</span>\n        </button>\n        <button onclick=\"printVisualReceipt()\" class=\"bg-brand-blue hover:bg-sky-700 text-white font-bold py-2.5 px-3 rounded-xl text-xs transition flex items-center justify-center space-x-1.5 shadow-sm\">\n          <i class=\"fa-solid fa-print\"></i>\n          <span>Imprimir</span>\n        </button>\n        <button onclick=\"deleteCurrentActiveReceipt()\" class=\"bg-red-600 hover:bg-red-700 text-white font-bold py-2.5 px-3 rounded-xl text-xs transition flex items-center justify-center space-x-1.5 shadow-sm\">\n          <i class=\"fa-solid fa-trash\"></i>\n          <span>Excluir</span>\n        </button>\n      </div>\n    </div>\n  </div>\n\n  <!-- MODAL: EDITAR RECIBO -->\n  <div id=\"editReceiptModal\" style=\"display: none;\" class=\"fixed inset-0 bg-slate-900/60 backdrop-blur-sm z-50 flex items-center justify-center p-4\">\n    <div class=\"bg-white border border-[#e2d7c5] rounded-3xl max-w-md w-full p-6 shadow-2xl animate-fade-in relative space-y-4\">\n      <div class=\"flex justify-between items-center pb-2 border-b border-slate-200\">\n        <h3 class=\"text-lg font-extrabold text-slate-900 flex items-center gap-2\">\n          <i class=\"fa-solid fa-pen-to-square text-brand-orange\"></i>\n          <span>Editar Dados do Recibo</span>\n        </h3>\n        <button onclick=\"closeEditReceiptModal()\" class=\"text-slate-400 hover:text-slate-700 text-2xl font-bold\">&times;</button>\n      </div>\n\n      <form id=\"editReceiptForm\" onsubmit=\"saveEditedReceipt(event)\" class=\"space-y-3.5\">\n        <input type=\"hidden\" id=\"editReceiptId\">\n\n        <div>\n          <label class=\"block text-xs font-bold text-slate-700 mb-1\">Código do Recibo *</label>\n          <input type=\"text\" id=\"editReceiptCode\" required class=\"w-full p-3 bg-white border border-slate-300 rounded-xl text-sm font-mono font-bold text-slate-900\">\n        </div>\n\n        <div>\n          <label class=\"block text-xs font-bold text-slate-700 mb-1\">Nome do Cliente *</label>\n          <input type=\"text\" id=\"editReceiptClientName\" required class=\"w-full p-3 bg-white border border-slate-300 rounded-xl text-sm font-bold text-slate-900\">\n        </div>\n\n        <div>\n          <label class=\"block text-xs font-bold text-slate-700 mb-1\">Plano Renovado *</label>\n          <input type=\"text\" id=\"editReceiptPlanName\" required class=\"w-full p-3 bg-white border border-slate-300 rounded-xl text-sm font-bold text-slate-900\">\n        </div>\n\n        <div class=\"grid grid-cols-2 gap-3\">\n          <div>\n            <label class=\"block text-xs font-bold text-slate-700 mb-1\">Valor Pago (R$) *</label>\n            <input type=\"number\" step=\"0.01\" id=\"editReceiptPrice\" required class=\"w-full p-3 bg-white border border-slate-300 rounded-xl text-sm font-bold text-slate-900\">\n          </div>\n\n          <div>\n            <label class=\"block text-xs font-bold text-slate-700 mb-1\">Data Pagamento *</label>\n            <input type=\"text\" id=\"editReceiptRenewedAt\" required class=\"w-full p-3 bg-white border border-slate-300 rounded-xl text-sm font-bold text-slate-900\">\n          </div>\n        </div>\n\n        <div>\n          <label class=\"block text-xs font-bold text-slate-700 mb-1\">Próximo Vencimento (AAAA-MM-DD) *</label>\n          <input type=\"date\" id=\"editReceiptNextDue\" required class=\"w-full p-3 bg-white border border-slate-300 rounded-xl text-sm font-bold text-slate-900\">\n        </div>\n\n        <div class=\"pt-2 flex justify-end space-x-2\">\n          <button type=\"button\" onclick=\"closeEditReceiptModal()\" class=\"bg-slate-200 hover:bg-slate-300 text-slate-700 font-bold px-4 py-2.5 rounded-xl text-xs\">Cancelar</button>\n          <button type=\"submit\" class=\"bg-brand-orange hover:bg-orange-600 text-white font-bold px-5 py-2.5 rounded-xl text-xs shadow-sm\">Salvar Alterações</button>\n        </div>\n      </form>\n    </div>\n  </div>\n\n  <!-- MODAL: ENVIAR MENSAGEM RÁPIDA WHATSAPP -->\n  <div id=\"quickMessageModal\" class=\"fixed inset-0 bg-slate-900/60 backdrop-blur-sm z-50 hidden flex items-center justify-center p-4\">\n    <div class=\"bg-white border border-[#e2d7c5] rounded-3xl max-w-lg w-full p-7 shadow-2xl animate-fade-in relative\">\n      <div class=\"flex justify-between items-center mb-4\">\n        <h3 class=\"text-xl font-extrabold text-slate-900 flex items-center gap-2\">\n          <i class=\"fa-brands fa-whatsapp text-emerald-600 text-2xl\"></i>\n          <span>Enviar Mensagem de Aviso</span>\n        </h3>\n        <button onclick=\"closeQuickMessageModal()\" class=\"text-slate-400 hover:text-slate-700 text-2xl font-bold\">&times;</button>\n      </div>\n\n      <div class=\"space-y-4\">\n        <div class=\"bg-[#f7f3ea] p-4 rounded-xl border border-[#e2d7c5]\">\n          <p class=\"text-xs font-bold text-slate-500 uppercase\">Cliente Selecionado</p>\n          <p id=\"qmClientName\" class=\"font-extrabold text-slate-900 text-base\">Nome do Cliente</p>\n          <p id=\"qmClientPhone\" class=\"text-xs font-mono text-slate-600\">5511999999999</p>\n        </div>\n\n        <div>\n          <label class=\"block text-sm font-bold text-slate-800 mb-1\">Selecione o Modelo de Aviso</label>\n          <select id=\"qmTemplateSelect\" onchange=\"updateQuickMessagePreview()\" class=\"w-full p-3.5 bg-white border border-slate-300 rounded-xl text-base font-bold text-slate-900 focus:outline-none\">\n            <option value=\"today\">🗓 Aviso: Vence HOJE</option>\n            <option value=\"tomorrow\">⏳ Aviso: Vence AMANHÃ (Falta 1 Dia)</option>\n            <option value=\"expired\">🔴 Aviso: Plano ATRASADO / VENCIDO</option>\n            <option value=\"renewed\">🎉 Aviso: Plano RENOVADO (Com Recibo)</option>\n          </select>\n        </div>\n\n        <div>\n          <label class=\"block text-sm font-bold text-slate-800 mb-1\">Mensagem a ser enviada</label>\n          <textarea id=\"qmMessageText\" rows=\"6\" class=\"w-full p-3.5 bg-white border border-slate-300 rounded-xl text-sm font-mono text-slate-900 focus:outline-none leading-relaxed\"></textarea>\n        </div>\n\n        <div class=\"grid grid-cols-1 sm:grid-cols-2 gap-3 pt-2\">\n          <button onclick=\"sendQuickMessageSocket()\" class=\"bg-emerald-600 hover:bg-emerald-700 text-white font-bold py-3 px-4 rounded-xl text-sm transition flex items-center justify-center space-x-2 shadow-sm\">\n            <i class=\"fa-solid fa-robot\"></i>\n            <span>Enviar via Robô</span>\n          </button>\n          <button onclick=\"openQuickMessageWhatsAppWeb()\" class=\"bg-brand-blue hover:bg-sky-700 text-white font-bold py-3 px-4 rounded-xl text-sm transition flex items-center justify-center space-x-2 shadow-sm\">\n            <i class=\"fa-brands fa-whatsapp\"></i>\n            <span>Abrir no WhatsApp</span>\n          </button>\n        </div>\n      </div>\n  <!-- BARRA DE NAVEGAÇÃO INFERIOR PARA CELULARES (MOBILE BOTTOM NAV BAR) -->\n  <div class=\"mobile-bottom-nav md:hidden\">\n    <button onclick=\"switchTab('dashboard')\" id=\"mobTab-dashboard\" class=\"mobile-bottom-btn active\">\n      <i class=\"fa-solid fa-chart-pie\"></i>\n      <span>Dashboard</span>\n    </button>\n    <button onclick=\"switchTab('clients')\" id=\"mobTab-clients\" class=\"mobile-bottom-btn\">\n      <i class=\"fa-solid fa-users\"></i>\n      <span>Clientes</span>\n    </button>\n    <button onclick=\"openClientModal()\" class=\"mobile-bottom-btn bg-brand-orange text-white px-3.5 py-3 rounded-full shadow-lg transform -translate-y-3 border-2 border-white\">\n      <i class=\"fa-solid fa-plus text-xl mb-0\"></i>\n    </button>\n    <button onclick=\"switchTab('receipts')\" id=\"mobTab-receipts\" class=\"mobile-bottom-btn\">\n      <i class=\"fa-solid fa-receipt\"></i>\n      <span>Recibos</span>\n    </button>\n    <button onclick=\"switchTab('whatsapp')\" id=\"mobTab-whatsapp\" class=\"mobile-bottom-btn\">\n      <i class=\"fa-brands fa-whatsapp\"></i>\n      <span>Robô IA</span>\n    </button>\n  </div>\n\n  \n<script>\n// Global State\nlet allClients = [];\nlet allPlans = [];\nlet allApps = [];\nlet allServers = [];\nlet crmViewMode = 'cards'; // 'cards' ou 'table'\nlet currentReceiptText = '';\nlet currentReceiptPhone = '';\nlet currentQuickClient = null;\nlet currentSettings = {};\nlet ws = null;\n\n// Inicialização da Página\ndocument.addEventListener('DOMContentLoaded', () => {\n  initWebSocket();\n  checkInitialWhatsAppStatus();\n  loadSettings();\n  loadPlans();\n  loadApps();\n  loadServers();\n  loadClients();\n  loadReceipts();\n  updateMenuPreview();\n});\n\nasync function checkInitialWhatsAppStatus() {\n  try {\n    const res = await fetch('/api/whatsapp/status');\n    const data = await res.json();\n    updateWhatsAppUI(data);\n  } catch (e) {\n    console.error('Erro ao verificar status inicial do WhatsApp:', e);\n  }\n}\n\n// === WEBSOCKET PARA QR CODE E STATUS DO WHATSAPP EM TEMPO REAL ===\nfunction initWebSocket() {\n  const protocol = window.location.protocol === 'https:' ? 'wss:' : 'ws:';\n  const wsUrl = `${protocol}//${window.location.host}`;\n\n  ws = new WebSocket(wsUrl);\n\n  ws.onmessage = (event) => {\n    try {\n      const data = JSON.parse(event.data);\n      if (data.type === 'STATUS_UPDATE') {\n        updateWhatsAppUI(data.payload);\n      }\n    } catch (e) {\n      console.error('Erro ao ler WebSocket:', e);\n    }\n  };\n\n  ws.onclose = () => {\n    setTimeout(initWebSocket, 3000);\n  };\n}\n\nfunction updateWhatsAppUI(payload) {\n  const statusBadge = document.getElementById('waStatusBadge');\n  const statusDot = document.getElementById('waStatusDot');\n  const statusText = document.getElementById('waStatusText');\n  const dashWaIcon = document.getElementById('dashWaIcon');\n  const dashWaText = document.getElementById('dashWaText');\n  const qrImg = document.getElementById('qrCodeImg');\n  const qrSpinner = document.getElementById('qrLoadingSpinner');\n  const waConnectStatusText = document.getElementById('waConnectStatusText');\n\n  if (!payload) return;\n\n  if (payload.status === 'connected') {\n    statusDot.className = 'w-3 h-3 rounded-full bg-emerald-500';\n    statusText.innerText = 'WhatsApp Conectado ✅';\n    statusBadge.className = 'flex items-center space-x-2.5 px-4 py-2 rounded-full bg-emerald-100 border border-emerald-300 text-sm font-bold text-emerald-800';\n\n    if (dashWaIcon) {\n      dashWaIcon.className = 'fa-solid fa-circle-check text-4xl text-emerald-600 mb-2';\n      dashWaText.innerText = 'Conectado e Atendendo 24h!';\n    }\n\n    if (qrImg) qrImg.classList.add('hidden');\n    if (qrSpinner) {\n      qrSpinner.classList.remove('hidden');\n      qrSpinner.innerHTML = `\n        <i class=\"fa-solid fa-circle-check text-5xl text-emerald-600 mb-2\"></i>\n        <span class=\"text-sm font-bold text-slate-800\">WhatsApp Conectado com Sucesso!</span>\n      `;\n    }\n    if (waConnectStatusText) waConnectStatusText.innerText = 'Seu robô de vendas está pronto e respondendo aos clientes!';\n\n  } else if (payload.qr) {\n    statusDot.className = 'w-3 h-3 rounded-full bg-yellow-500 animate-pulse';\n    statusText.innerText = 'Escaneie o QR Code 📱';\n    statusBadge.className = 'flex items-center space-x-2.5 px-4 py-2 rounded-full bg-amber-100 border border-amber-300 text-sm font-bold text-amber-900';\n\n    if (dashWaIcon) {\n      dashWaIcon.className = 'fa-solid fa-qrcode text-4xl text-amber-600 mb-2 animate-bounce';\n      dashWaText.innerText = 'Aguardando Escanear QR Code';\n    }\n\n    if (qrSpinner) qrSpinner.classList.add('hidden');\n    if (qrImg) {\n      qrImg.src = payload.qr;\n      qrImg.classList.remove('hidden');\n    }\n    if (waConnectStatusText) waConnectStatusText.innerText = 'Abra o WhatsApp no celular e escaneie o código acima!';\n\n  } else {\n    statusDot.className = 'w-3 h-3 rounded-full bg-red-500';\n    statusText.innerText = 'WhatsApp Desconectado 🔴';\n    statusBadge.className = 'flex items-center space-x-2.5 px-4 py-2 rounded-full bg-red-100 border border-red-300 text-sm font-bold text-red-800';\n\n    if (dashWaIcon) {\n      dashWaIcon.className = 'fa-solid fa-plug-circle-xmark text-4xl text-red-600 mb-2';\n      dashWaText.innerText = 'Desconectado';\n    }\n\n    if (qrImg) qrImg.classList.add('hidden');\n    if (qrSpinner) {\n      qrSpinner.classList.remove('hidden');\n      qrSpinner.innerHTML = `\n        <i class=\"fa-solid fa-circle-notch fa-spin text-4xl text-brand-blue mb-2\"></i>\n        <span class=\"text-xs font-bold\">Gerando novo código QR...</span>\n      `;\n    }\n    if (waConnectStatusText) waConnectStatusText.innerText = 'Iniciando módulo de conexão...';\n  }\n}\n\nasync function reconnectWhatsApp() {\n  try {\n    const res = await fetch('/api/whatsapp/connect', { method: 'POST' });\n    const data = await res.json();\n    alert(data.message || 'Solicitada nova reconexão.');\n  } catch (e) {\n    alert('Erro ao reconectar: ' + e.message);\n  }\n}\n\n// === NAVEGAÇÃO DE ABAS ===\nfunction switchTab(tabId) {\n  document.querySelectorAll('.tab-content').forEach(el => el.classList.add('hidden'));\n  document.querySelectorAll('.nav-tab').forEach(el => el.classList.remove('active'));\n  document.querySelectorAll('.mobile-bottom-btn').forEach(el => el.classList.remove('active'));\n\n  const targetTab = document.getElementById(`tab-${tabId}`);\n  const targetBtn = document.getElementById(`tabBtn-${tabId}`);\n  const targetMobBtn = document.getElementById(`mobTab-${tabId}`);\n\n  if (targetTab) targetTab.classList.remove('hidden');\n  if (targetBtn) targetBtn.classList.add('active');\n  if (targetMobBtn) targetMobBtn.classList.add('active');\n\n  if (tabId === 'receipts') {\n    loadReceipts();\n  }\n\n  window.scrollTo({ top: 0, behavior: 'smooth' });\n}\n\n// === CARDS DE PLANOS DE CANAIS COM CORES PERSONALIZADAS ===\nasync function loadPlans() {\n  try {\n    const res = await fetch('/api/plans');\n    allPlans = await res.json();\n    renderPlans(allPlans);\n    populatePlanSelectDropdown();\n  } catch (e) {\n    console.error('Erro ao carregar planos:', e);\n  }\n}\n\nfunction renderPlans(plans) {\n  const container = document.getElementById('plansGrid');\n  if (!container) return;\n  container.innerHTML = '';\n\n  if (!plans || plans.length === 0) {\n    container.innerHTML = `<div class=\"col-span-full text-center py-8 text-slate-500 font-medium bg-white p-6 rounded-2xl border border-[#e2d7c5]\">Nenhum card de plano cadastrado ainda.</div>`;\n    return;\n  }\n\n  plans.forEach(p => {\n    const cardColor = p.color || '#0284c7';\n    const card = document.createElement('div');\n    card.className = 'bg-white rounded-2xl border-2 p-6 shadow-md relative flex flex-col justify-between transition transform hover:-translate-y-1';\n    card.style.borderColor = cardColor;\n\n    card.innerHTML = `\n      <div>\n        <div class=\"flex items-center justify-between mb-3\">\n          <span class=\"text-xs font-extrabold uppercase px-3 py-1 rounded-full text-white shadow-sm\" style=\"background-color: ${cardColor}\">\n            Plano IPTV\n          </span>\n          <button onclick=\"deletePlan(${p.id})\" class=\"text-slate-400 hover:text-red-600 transition p-1\" title=\"Excluir Plano\">\n            <i class=\"fa-solid fa-trash text-base\"></i>\n          </button>\n        </div>\n\n        <h3 class=\"text-xl font-extrabold text-slate-900 mb-2\">${p.name}</h3>\n        <p class=\"text-3xl font-extrabold mb-4\" style=\"color: ${cardColor}\">\n          R$ ${parseFloat(p.price).toFixed(2)} <span class=\"text-xs text-slate-500 font-normal\">/mês</span>\n        </p>\n\n        <p class=\"text-sm text-slate-600 mb-4 font-medium leading-relaxed\">\n          ${p.description || 'Canais em HD, FHD e 4K + Filmes e Séries atualizados'}\n        </p>\n      </div>\n\n      <div class=\"pt-4 border-t border-slate-100 flex items-center justify-between text-xs text-slate-500 font-bold\">\n        <span><i class=\"fa-solid fa-check text-emerald-600 mr-1\"></i> Liberação Imediata</span>\n        <span><i class=\"fa-solid fa-bolt text-amber-500 mr-1\"></i> Suporte 24h</span>\n      </div>\n    `;\n\n    container.appendChild(card);\n  });\n}\n\nfunction populatePlanSelectDropdown() {\n  const select = document.getElementById('clientPlanSelect');\n  if (!select) return;\n  select.innerHTML = '<option value=\"\">-- Selecionar da Lista de Planos --</option>';\n\n  allPlans.forEach(p => {\n    const opt = document.createElement('option');\n    opt.value = p.name;\n    opt.dataset.price = p.price;\n    opt.innerText = `${p.name} - R$ ${parseFloat(p.price).toFixed(2)}`;\n    select.appendChild(opt);\n  });\n}\n\nfunction onClientPlanSelectChange() {\n  const select = document.getElementById('clientPlanSelect');\n  const selectedOpt = select.options[select.selectedIndex];\n  if (selectedOpt && selectedOpt.dataset.price) {\n    document.getElementById('clientPlanName').value = selectedOpt.value;\n    document.getElementById('clientPrice').value = selectedOpt.dataset.price;\n  }\n}\n\nasync function saveNewPlan(e) {\n  e.preventDefault();\n  const name = document.getElementById('newPlanName').value.trim();\n  const price = parseFloat(document.getElementById('newPlanPrice').value);\n  const color = document.getElementById('newPlanColor').value;\n  const description = document.getElementById('newPlanDesc').value.trim();\n\n  if (!name || isNaN(price)) {\n    alert('Preencha o nome e valor do plano.');\n    return;\n  }\n\n  try {\n    await fetch('/api/plans', {\n      method: 'POST',\n      headers: { 'Content-Type': 'application/json' },\n      body: JSON.stringify({ name, price, color, description })\n    });\n    document.getElementById('newPlanName').value = '';\n    document.getElementById('newPlanPrice').value = '';\n    document.getElementById('newPlanDesc').value = '';\n    loadPlans();\n    alert('🎨 Novo card de plano cadastrado com sucesso!');\n  } catch (err) {\n    alert('Erro ao salvar plano: ' + err.message);\n  }\n}\n\nasync function deletePlan(id) {\n  if (!confirm('Deseja excluir este plano de canais?')) return;\n  try {\n    await fetch(`/api/plans/${id}`, { method: 'DELETE' });\n    loadPlans();\n  } catch (err) {\n    alert('Erro ao excluir plano: ' + err.message);\n  }\n}\n\n// === GERENCIAMENTO DE APPLICATIVOS E SERVIDORES ===\nasync function loadApps() {\n  try {\n    const res = await fetch('/api/apps');\n    allApps = await res.json();\n    renderApps(allApps);\n    populateAppDropdown();\n  } catch (e) {\n    console.error('Erro ao carregar apps:', e);\n  }\n}\n\nfunction renderApps(apps) {\n  const container = document.getElementById('appsList');\n  if (!container) return;\n  container.innerHTML = '';\n\n  if (!apps || apps.length === 0) {\n    container.innerHTML = `<div class=\"p-3 text-center text-xs text-slate-500\">Nenhum aplicativo cadastrado.</div>`;\n    return;\n  }\n\n  apps.forEach(a => {\n    const item = document.createElement('div');\n    item.className = 'p-3 rounded-xl bg-[#f7f3ea] border border-[#e2d7c5] flex items-center justify-between text-sm font-bold text-slate-900';\n    item.innerHTML = `\n      <span class=\"flex items-center gap-2\">\n        <i class=\"fa-solid fa-mobile-screen text-purple-600\"></i> ${a.name}\n      </span>\n      <button onclick=\"deleteApp(${a.id})\" class=\"text-slate-400 hover:text-red-600 transition p-1\"><i class=\"fa-solid fa-trash\"></i></button>\n    `;\n    container.appendChild(item);\n  });\n}\n\nfunction populateAppDropdown() {\n  const select = document.getElementById('clientAppSelect');\n  if (!select) return;\n  select.innerHTML = '<option value=\"\">-- Nenhum App Selecionado --</option>';\n\n  allApps.forEach(a => {\n    const opt = document.createElement('option');\n    opt.value = a.name;\n    opt.innerText = a.name;\n    select.appendChild(opt);\n  });\n}\n\nasync function saveNewApp(e) {\n  e.preventDefault();\n  const name = document.getElementById('newAppName').value.trim();\n  if (!name) return;\n\n  try {\n    await fetch('/api/apps', {\n      method: 'POST',\n      headers: { 'Content-Type': 'application/json' },\n      body: JSON.stringify({ name })\n    });\n    document.getElementById('newAppName').value = '';\n    loadApps();\n    alert('📱 Aplicativo cadastrado com sucesso!');\n  } catch (e) {\n    alert('Erro ao cadastrar aplicativo: ' + e.message);\n  }\n}\n\nasync function deleteApp(id) {\n  if (!confirm('Deseja excluir este aplicativo?')) return;\n  try {\n    await fetch(`/api/apps/${id}`, { method: 'DELETE' });\n    loadApps();\n  } catch (e) {\n    alert('Erro ao excluir app: ' + e.message);\n  }\n}\n\nasync function loadServers() {\n  try {\n    const res = await fetch('/api/servers');\n    allServers = await res.json();\n    renderServers(allServers);\n    populateServerDropdown();\n  } catch (e) {\n    console.error('Erro ao carregar servidores:', e);\n  }\n}\n\nfunction renderServers(servers) {\n  const container = document.getElementById('serversList');\n  if (!container) return;\n  container.innerHTML = '';\n\n  if (!servers || servers.length === 0) {\n    container.innerHTML = `<div class=\"p-3 text-center text-xs text-slate-500\">Nenhum servidor cadastrado.</div>`;\n    return;\n  }\n\n  servers.forEach(s => {\n    const item = document.createElement('div');\n    item.className = 'p-3 rounded-xl bg-[#f7f3ea] border border-[#e2d7c5] flex items-center justify-between text-sm font-bold text-slate-900';\n    item.innerHTML = `\n      <span class=\"flex items-center gap-2\">\n        <i class=\"fa-solid fa-server text-brand-blue\"></i> ${s.name}\n      </span>\n      <button onclick=\"deleteServer(${s.id})\" class=\"text-slate-400 hover:text-red-600 transition p-1\"><i class=\"fa-solid fa-trash\"></i></button>\n    `;\n    container.appendChild(item);\n  });\n}\n\nfunction populateServerDropdown() {\n  const select = document.getElementById('clientServerSelect');\n  if (!select) return;\n  select.innerHTML = '<option value=\"\">-- Nenhum Servidor Selecionado --</option>';\n\n  allServers.forEach(s => {\n    const opt = document.createElement('option');\n    opt.value = s.name;\n    opt.innerText = s.name;\n    select.appendChild(opt);\n  });\n}\n\nasync function saveNewServer(e) {\n  e.preventDefault();\n  const name = document.getElementById('newServerName').value.trim();\n  if (!name) return;\n\n  try {\n    await fetch('/api/servers', {\n      method: 'POST',\n      headers: { 'Content-Type': 'application/json' },\n      body: JSON.stringify({ name })\n    });\n    document.getElementById('newServerName').value = '';\n    loadServers();\n    alert('🖥 Servidor cadastrado com sucesso!');\n  } catch (e) {\n    alert('Erro ao cadastrar servidor: ' + e.message);\n  }\n}\n\nasync function deleteServer(id) {\n  if (!confirm('Deseja excluir este servidor?')) return;\n  try {\n    await fetch(`/api/servers/${id}`, { method: 'DELETE' });\n    loadServers();\n  } catch (e) {\n    alert('Erro ao excluir servidor: ' + e.message);\n  }\n}\n\n// === CONFIGURAÇÕES DO SISTEMA & IA ===\nasync function loadSettings() {\n  try {\n    const res = await fetch('/api/settings');\n    currentSettings = await res.json();\n\n    if (currentSettings.company_name) {\n      document.getElementById('companyNameInput').value = currentSettings.company_name;\n      document.getElementById('headerCompanyName').innerText = currentSettings.company_name;\n    }\n    if (currentSettings.bot_enabled) {\n      document.getElementById('botEnabledSelect').value = currentSettings.bot_enabled;\n    }\n    if (currentSettings.gemini_api_key) {\n      document.getElementById('geminiApiKey').value = currentSettings.gemini_api_key;\n    }\n    if (currentSettings.system_prompt) {\n      document.getElementById('systemPromptText').value = currentSettings.system_prompt;\n    }\n    if (currentSettings.test_duration) {\n      document.getElementById('testDuration').value = currentSettings.test_duration;\n    }\n    if (currentSettings.pix_key) {\n      document.getElementById('pixKeyInput').value = currentSettings.pix_key;\n    }\n    if (currentSettings.company_logo) {\n      updateLogoPreviewUI(currentSettings.company_logo);\n    }\n\n    updateMenuPreview();\n  } catch (e) {\n    console.error('Erro ao carregar configurações:', e);\n  }\n}\n\nasync function uploadLogoFile(event) {\n  const file = event.target.files[0];\n  if (!file) return;\n\n  if (file.size > 10 * 1024 * 1024) {\n    alert('A imagem é muito grande. Por favor escolha uma imagem de até 10MB.');\n    return;\n  }\n\n  const reader = new FileReader();\n  reader.onload = async (e) => {\n    const base64Data = e.target.result;\n\n    try {\n      const res = await fetch('/api/upload-logo', {\n        method: 'POST',\n        headers: { 'Content-Type': 'application/json' },\n        body: JSON.stringify({ imageBase64: base64Data, filename: file.name })\n      });\n      const data = await res.json();\n      if (data.success) {\n        currentSettings.company_logo = data.logo_url;\n        updateLogoPreviewUI(data.logo_url);\n        alert('🖼️ Foto da Logo da empresa enviada e salva com sucesso!');\n      } else {\n        alert('Erro ao enviar foto da logo: ' + (data.error || 'Erro desconhecido'));\n      }\n    } catch (err) {\n      alert('Erro ao fazer upload da logo: ' + err.message);\n    }\n  };\n  reader.readAsDataURL(file);\n}\n\nfunction updateLogoPreviewUI(url) {\n  const previewImg = document.getElementById('logoPreviewImg');\n  const previewIcon = document.getElementById('logoPreviewIcon');\n  const companyLogoInput = document.getElementById('companyLogoInput');\n  const headerLogoImg = document.getElementById('headerLogoImg');\n  const headerLogoIcon = document.getElementById('headerLogoIcon');\n\n  if (companyLogoInput) companyLogoInput.value = url || '';\n\n  if (url && url.trim().length > 3) {\n    if (previewImg) {\n      previewImg.src = url;\n      previewImg.style.objectFit = 'contain';\n      previewImg.classList.remove('hidden');\n    }\n    if (previewIcon) previewIcon.classList.add('hidden');\n\n    if (headerLogoImg) {\n      headerLogoImg.src = url;\n      headerLogoImg.style.objectFit = 'contain';\n      headerLogoImg.classList.remove('hidden');\n    }\n    if (headerLogoIcon) headerLogoIcon.classList.add('hidden');\n  } else {\n    if (previewImg) previewImg.classList.add('hidden');\n    if (previewIcon) previewIcon.classList.remove('hidden');\n\n    if (headerLogoImg) headerLogoImg.classList.add('hidden');\n    if (headerLogoIcon) headerLogoIcon.classList.remove('hidden');\n  }\n}\n\nasync function removeLogoFile() {\n  if (!confirm('Deseja remover a foto da logo da empresa?')) return;\n  try {\n    await fetch('/api/settings', {\n      method: 'POST',\n      headers: { 'Content-Type': 'application/json' },\n      body: JSON.stringify({ settings: { company_logo: '' } })\n    });\n    currentSettings.company_logo = '';\n    updateLogoPreviewUI('');\n    alert('Foto da logo removida com sucesso.');\n  } catch (e) {\n    alert('Erro ao remover logo: ' + e.message);\n  }\n}\n\nasync function saveCompanySettings(e) {\n  e.preventDefault();\n  const settings = {\n    company_name: document.getElementById('companyNameInput').value.trim(),\n    bot_enabled: document.getElementById('botEnabledSelect').value\n  };\n\n  try {\n    await fetch('/api/settings', {\n      method: 'POST',\n      headers: { 'Content-Type': 'application/json' },\n      body: JSON.stringify({ settings })\n    });\n    alert('Dados da empresa salvos com sucesso!');\n    loadSettings();\n  } catch (e) {\n    alert('Erro ao salvar empresa: ' + e.message);\n  }\n}\n\nasync function saveAiSettings(e) {\n  e.preventDefault();\n  const settings = {\n    gemini_api_key: document.getElementById('geminiApiKey').value.trim(),\n    system_prompt: document.getElementById('systemPromptText').value,\n    test_duration: document.getElementById('testDuration').value.trim(),\n    pix_key: document.getElementById('pixKeyInput').value.trim(),\n    company_logo: document.getElementById('companyLogoInput') ? document.getElementById('companyLogoInput').value.trim() : ''\n  };\n\n  try {\n    await fetch('/api/settings', {\n      method: 'POST',\n      headers: { 'Content-Type': 'application/json' },\n      body: JSON.stringify({ settings })\n    });\n    alert('Configurações salvas com sucesso!');\n    loadSettings();\n  } catch (e) {\n    alert('Erro ao salvar IA: ' + e.message);\n  }\n}\n\nasync function appendQuickInfoToPrompt() {\n  const input = document.getElementById('quickPromptInfoInput');\n  const text = input ? input.value.trim() : '';\n\n  if (!text) {\n    alert('Por favor, digite a informação que deseja adicionar ao prompt.');\n    return;\n  }\n\n  const textarea = document.getElementById('systemPromptText');\n  const currentPrompt = textarea ? textarea.value : '';\n  const dateStr = new Date().toLocaleDateString('pt-BR');\n  \n  const newPrompt = currentPrompt + `\\n\\n📌 [Informação Adicionada em ${dateStr}]:\\n- ${text}`;\n  textarea.value = newPrompt;\n\n  const settings = { system_prompt: newPrompt };\n\n  try {\n    await fetch('/api/settings', {\n      method: 'POST',\n      headers: { 'Content-Type': 'application/json' },\n      body: JSON.stringify({ settings })\n    });\n    alert('✨ Nova informação anexada com sucesso ao Prompt Geral do sistema!');\n    input.value = '';\n    loadSettings();\n  } catch (e) {\n    alert('Erro ao salvar no prompt: ' + e.message);\n  }\n}\n\nfunction updateMenuPreview() {\n  const company = currentSettings.company_name || 'IPTV CLIENTES';\n  const preview = `🤖 *Atendimento Automático - ${company}*\n\nOlá! Seja muito bem-vindo(a)! 👋\nSou o assistente virtual da *${company}*.\n\nComo posso te ajudar hoje? Por favor, escolha uma das opções abaixo digitando apenas o *número* correspondente:\n\n1️⃣ *Consultar Vencimento & Chave Pix*\n2️⃣ *Solicitar Teste Grátis*\n3️⃣ *Ver Planos e Preços*\n4️⃣ *Tirar Dúvidas com Atendente (IA)*\n\n_Digite o número da opção desejada:_`;\n  \n  const box = document.getElementById('menuPreviewBox');\n  if (box) box.innerText = preview;\n}\n\n// === CLIENTES (CRM - MODO CARDS E MODO TABELA) ===\nasync function loadClients() {\n  try {\n    const res = await fetch('/api/clients');\n    if (!res.ok) throw new Error('Erro HTTP na API /api/clients: ' + res.status);\n    const data = await res.json();\n    allClients = Array.isArray(data) ? data : [];\n    renderClients(allClients);\n    updateDashboardStats(allClients);\n  } catch (e) {\n    console.error('Erro ao carregar clientes:', e);\n    allClients = Array.isArray(allClients) ? allClients : [];\n    renderClients(allClients);\n  }\n}\n\nfunction setCrmViewMode(mode) {\n  crmViewMode = mode;\n\n  const btnCards = document.getElementById('viewBtnCards');\n  const btnTable = document.getElementById('viewBtnTable');\n  const cardsGrid = document.getElementById('clientsCardsGrid');\n  const tableView = document.getElementById('clientsTableView');\n\n  if (mode === 'cards') {\n    btnCards.className = 'px-4 py-2 rounded-lg text-sm font-bold transition bg-brand-blue text-white shadow-sm';\n    btnTable.className = 'px-4 py-2 rounded-lg text-sm font-bold text-slate-700 hover:text-slate-900 transition';\n    cardsGrid.classList.remove('hidden');\n    tableView.classList.add('hidden');\n  } else {\n    btnTable.className = 'px-4 py-2 rounded-lg text-sm font-bold transition bg-brand-blue text-white shadow-sm';\n    btnCards.className = 'px-4 py-2 rounded-lg text-sm font-bold text-slate-700 hover:text-slate-900 transition';\n    tableView.classList.remove('hidden');\n    cardsGrid.classList.add('hidden');\n  }\n\n  filterClients();\n}\n\nfunction renderClients(clients) {\n  renderClientCards(clients);\n  renderClientTable(clients);\n}\n\nfunction formatWaUrl(phone) {\n  if (!phone) return '#';\n  let clean = phone.replace(/\\D/g, '');\n  if (clean.length === 10 || clean.length === 11) {\n    clean = '55' + clean;\n  }\n  return `https://wa.me/${clean}`;\n}\n\n// RENDERIZADOR 1: MODO CARDS (CARDS INDIVIDUAIS COM TODAS AS INFORMAÇÕES DO CLIENTE)\nfunction renderClientCards(clients) {\n  const grid = document.getElementById('clientsCardsGrid');\n  if (!grid) return;\n  grid.innerHTML = '';\n\n  if (!clients || clients.length === 0) {\n    grid.innerHTML = `<div class=\"col-span-full text-center py-10 text-slate-500 font-medium bg-white p-6 rounded-2xl border border-[#e2d7c5]\">Nenhum cliente encontrado.</div>`;\n    return;\n  }\n\n  const today = new Date().toISOString().split('T')[0];\n\n  clients.forEach(c => {\n    const card = document.createElement('div');\n    card.className = 'bg-white border-2 border-[#e2d7c5] rounded-3xl p-6 shadow-md relative flex flex-col justify-between transition transform hover:-translate-y-1';\n\n    const due = new Date(c.due_date + 'T00:00:00');\n    const now = new Date(today + 'T00:00:00');\n    const diffDays = Math.ceil((due - now) / (1000 * 60 * 60 * 24));\n\n    let statusBadge = '';\n    if (diffDays < 0) {\n      statusBadge = `<span class=\"bg-red-100 text-red-700 border border-red-300 px-3 py-1 rounded-full text-xs font-extrabold\">🔴 Vencido (${Math.abs(diffDays)}d atrás)</span>`;\n    } else if (diffDays <= 3) {\n      statusBadge = `<span class=\"bg-orange-100 text-orange-800 border border-orange-300 px-3 py-1 rounded-full text-xs font-extrabold\">🟠 Vence em ${diffDays} dia(s)</span>`;\n    } else {\n      statusBadge = `<span class=\"bg-emerald-100 text-emerald-800 border border-emerald-300 px-3 py-1 rounded-full text-xs font-extrabold\">🟢 Ativo (${diffDays}d restantes)</span>`;\n    }\n\n    const dueDateFormatted = c.due_date ? c.due_date.split('-').reverse().join('/') : '-';\n    const code = c.client_code || `#${1000 + c.id}`;\n    const waLink = formatWaUrl(c.phone);\n\n    card.innerHTML = `\n      <div>\n        <!-- Card Header: Código e Status Badge -->\n        <div class=\"flex items-center justify-between mb-3\">\n          <span class=\"font-mono font-extrabold text-brand-orange text-sm bg-orange-50 border border-orange-200 px-2.5 py-1 rounded-lg\">\n            ${code}\n          </span>\n          ${statusBadge}\n        </div>\n\n        <!-- Nome do Cliente & Telefone -->\n        <h3 class=\"text-xl font-extrabold text-slate-900 tracking-tight\">${c.name}</h3>\n        <p class=\"text-sm font-mono text-slate-600 mb-4 flex items-center gap-1.5 font-bold\">\n          <a href=\"${waLink}\" target=\"_blank\" class=\"hover:text-emerald-600 text-slate-800 flex items-center gap-1.5\">\n            <i class=\"fa-brands fa-whatsapp text-emerald-600 text-base\"></i> ${c.phone}\n          </a>\n        </p>\n\n        <!-- Informações do Plano & Valor -->\n        <div class=\"bg-[#f7f3ea] p-3.5 rounded-2xl border border-[#e2d7c5] mb-4 space-y-2\">\n          <div class=\"flex items-center justify-between\">\n            <span class=\"text-xs font-bold text-slate-500 uppercase\">Plano Contratado</span>\n            <span class=\"text-sm font-extrabold text-brand-orange\">R$ ${parseFloat(c.price).toFixed(2)}</span>\n          </div>\n          <p class=\"font-extrabold text-slate-900 text-base\">${c.plan_name}</p>\n\n          <!-- Badges de App e Servidor -->\n          <div class=\"flex flex-wrap gap-2 pt-1 border-t border-[#e2d7c5]\">\n            <span class=\"text-xs font-bold bg-purple-100 text-purple-800 border border-purple-200 px-2.5 py-1 rounded-lg flex items-center gap-1\">\n              <i class=\"fa-solid fa-mobile-screen-button\"></i> ${c.app_name || 'App Não Informado'}\n            </span>\n            <span class=\"text-xs font-bold bg-sky-100 text-sky-800 border border-sky-200 px-2.5 py-1 rounded-lg flex items-center gap-1\">\n              <i class=\"fa-solid fa-server\"></i> ${c.server_name || 'Servidor Não Informado'}\n            </span>\n          </div>\n        </div>\n\n        <!-- Data de Vencimento e Notas -->\n        <div class=\"flex items-center justify-between text-xs font-bold text-slate-700 mb-4\">\n          <span>🗓 Vencimento: <b class=\"text-slate-900 text-sm\">${dueDateFormatted}</b></span>\n          ${c.notes ? `<span class=\"text-slate-500 font-normal truncate max-w-[140px]\">${c.notes}</span>` : ''}\n        </div>\n      </div>\n\n      <!-- Card Actions -->\n      <div class=\"pt-4 border-t border-slate-100 flex items-center justify-between gap-2\">\n        <button onclick=\"renewClient(${c.id})\" class=\"flex-1 bg-emerald-600 hover:bg-emerald-700 text-white font-extrabold text-xs py-2.5 px-3 rounded-xl shadow-sm transition flex items-center justify-center gap-1\">\n          <i class=\"fa-solid fa-circle-check\"></i> Dar Baixa\n        </button>\n\n        <button onclick=\"openQuickMessageModal(${c.id})\" class=\"flex-1 bg-brand-blue hover:bg-sky-700 text-white font-extrabold text-xs py-2.5 px-3 rounded-xl shadow-sm transition flex items-center justify-center gap-1\">\n          <i class=\"fa-brands fa-whatsapp\"></i> Aviso\n        </button>\n\n        <button onclick=\"editClient(${c.id})\" class=\"text-slate-600 hover:text-brand-blue p-2 font-bold text-base\" title=\"Editar\"><i class=\"fa-solid fa-pen-to-square\"></i></button>\n        <button onclick=\"deleteClient(${c.id})\" class=\"text-slate-600 hover:text-red-600 p-2 font-bold text-base\" title=\"Excluir\"><i class=\"fa-solid fa-trash\"></i></button>\n      </div>\n    `;\n\n    grid.appendChild(card);\n  });\n}\n\n// RENDERIZADOR 2: MODO TABELA (LISTAGEM TRADICIONAL)\nfunction renderClientTable(clients) {\n  const tbody = document.getElementById('clientsTableBody');\n  if (!tbody) return;\n  tbody.innerHTML = '';\n\n  if (!clients || clients.length === 0) {\n    tbody.innerHTML = `<tr><td colspan=\"8\" class=\"text-center py-8 text-slate-500 font-medium\">Nenhum cliente encontrado.</td></tr>`;\n    return;\n  }\n\n  const today = new Date().toISOString().split('T')[0];\n\n  clients.forEach(c => {\n    const tr = document.createElement('tr');\n    tr.className = 'hover:bg-amber-50/80 transition border-b border-[#e2d7c5]';\n\n    const due = new Date(c.due_date + 'T00:00:00');\n    const now = new Date(today + 'T00:00:00');\n    const diffDays = Math.ceil((due - now) / (1000 * 60 * 60 * 24));\n\n    let statusBadge = '';\n    if (diffDays < 0) {\n      statusBadge = `<span class=\"bg-red-100 text-red-700 border border-red-300 px-3 py-1 rounded-full text-xs font-extrabold\">🔴 Vencido (${Math.abs(diffDays)}d atrás)</span>`;\n    } else if (diffDays <= 3) {\n      statusBadge = `<span class=\"bg-orange-100 text-orange-800 border border-orange-300 px-3 py-1 rounded-full text-xs font-extrabold\">🟠 Vence em ${diffDays} dia(s)</span>`;\n    } else {\n      statusBadge = `<span class=\"bg-emerald-100 text-emerald-800 border border-emerald-300 px-3 py-1 rounded-full text-xs font-extrabold\">🟢 Ativo (${diffDays}d restantes)</span>`;\n    }\n\n    const dueDateFormatted = c.due_date ? c.due_date.split('-').reverse().join('/') : '-';\n    const code = c.client_code || `#${1000 + c.id}`;\n    const waLink = formatWaUrl(c.phone);\n\n    tr.innerHTML = `\n      <td class=\"py-4 px-4 font-mono font-extrabold text-brand-orange text-sm\">\n        ${code}\n      </td>\n      <td class=\"py-4 px-4 font-bold text-slate-900 text-base\">\n        ${c.name}\n        ${c.notes ? `<p class=\"text-xs text-slate-500 font-normal mt-0.5\">${c.notes}</p>` : ''}\n      </td>\n      <td class=\"py-4 px-4 text-slate-700 font-mono text-sm\">\n        <a href=\"${waLink}\" target=\"_blank\" class=\"hover:text-emerald-600 font-bold flex items-center gap-1.5 text-slate-800\">\n          <i class=\"fa-brands fa-whatsapp text-emerald-600 text-base\"></i> ${c.phone}\n        </a>\n      </td>\n      <td class=\"py-4 px-4 text-slate-800\">\n        <span class=\"font-bold text-slate-900\">${c.plan_name}</span>\n        <p class=\"text-sm text-brand-orange font-extrabold\">R$ ${parseFloat(c.price).toFixed(2)}</p>\n      </td>\n      <td class=\"py-4 px-4 text-xs font-bold text-slate-700\">\n        <span class=\"block text-purple-700\">📱 ${c.app_name || '-'}</span>\n        <span class=\"block text-sky-700\">🖥 ${c.server_name || '-'}</span>\n      </td>\n      <td class=\"py-4 px-4 font-bold text-slate-900\">\n        🗓 ${dueDateFormatted}\n      </td>\n      <td class=\"py-4 px-4\">${statusBadge}</td>\n      <td class=\"py-4 px-4 text-right space-x-1.5\">\n        <button onclick=\"renewClient(${c.id})\" class=\"bg-emerald-600 hover:bg-emerald-700 text-white font-extrabold text-xs px-3 py-2 rounded-xl shadow-sm transition inline-flex items-center gap-1\">\n          <i class=\"fa-solid fa-circle-check\"></i> Baixa\n        </button>\n        <button onclick=\"openQuickMessageModal(${c.id})\" class=\"bg-brand-blue hover:bg-sky-700 text-white font-extrabold text-xs px-3 py-2 rounded-xl shadow-sm transition inline-flex items-center gap-1\">\n          <i class=\"fa-brands fa-whatsapp\"></i> Aviso\n        </button>\n        <button onclick=\"editClient(${c.id})\" class=\"text-slate-600 hover:text-brand-blue p-2 font-bold text-base\"><i class=\"fa-solid fa-pen-to-square\"></i></button>\n        <button onclick=\"deleteClient(${c.id})\" class=\"text-slate-600 hover:text-red-600 p-2 font-bold text-base\"><i class=\"fa-solid fa-trash\"></i></button>\n      </td>\n    `;\n\n    tbody.appendChild(tr);\n  });\n}\n\nfunction filterClients() {\n  const input = document.getElementById('searchClientInput');\n  const select = document.getElementById('filterStatusSelect');\n  if (!input || !select) return;\n\n  const query = input.value.toLowerCase().trim();\n  const status = select.value;\n\n  const filtered = allClients.filter(c => {\n    const code = (c.client_code || `#${1000 + c.id}`).toLowerCase();\n    const app = (c.app_name || '').toLowerCase();\n    const server = (c.server_name || '').toLowerCase();\n\n    const matchesSearch = c.name.toLowerCase().includes(query) || c.phone.includes(query) || c.plan_name.toLowerCase().includes(query) || code.includes(query) || app.includes(query) || server.includes(query);\n    \n    const today = new Date().toISOString().split('T')[0];\n    const due = new Date(c.due_date + 'T00:00:00');\n    const now = new Date(today + 'T00:00:00');\n    const diffDays = Math.ceil((due - now) / (1000 * 60 * 60 * 24));\n\n    let matchesStatus = true;\n    if (status === 'active') matchesStatus = (diffDays > 3);\n    if (status === 'expiring') matchesStatus = (diffDays >= 0 && diffDays <= 3);\n    if (status === 'expired') matchesStatus = (diffDays < 0);\n\n    return matchesSearch && matchesStatus;\n  });\n\n  renderClients(filtered);\n}\n\nfunction updateDashboardStats(clients) {\n  const total = clients.length;\n  const today = new Date().toISOString().split('T')[0];\n\n  let active = 0;\n  let expiring = 0;\n  let expired = 0;\n  let revenue = 0;\n\n  const oneDayList = [];\n  const expiredList = [];\n\n  clients.forEach(c => {\n    revenue += parseFloat(c.price || 0);\n\n    const due = new Date(c.due_date + 'T00:00:00');\n    const now = new Date(today + 'T00:00:00');\n    const diffDays = Math.ceil((due - now) / (1000 * 60 * 60 * 24));\n\n    if (diffDays < 0) {\n      expired++;\n      expiredList.push({ ...c, diffDays });\n    } else if (diffDays <= 3) {\n      expiring++;\n      if (diffDays <= 1) {\n        oneDayList.push({ ...c, diffDays });\n      }\n    } else {\n      active++;\n    }\n  });\n\n  if (document.getElementById('statTotalClients')) document.getElementById('statTotalClients').innerText = total;\n  if (document.getElementById('statActiveClients')) document.getElementById('statActiveClients').innerText = active;\n  if (document.getElementById('statExpiringClients')) document.getElementById('statExpiringClients').innerText = expiring;\n  if (document.getElementById('statExpiredClients')) document.getElementById('statExpiredClients').innerText = expired;\n  if (document.getElementById('statMonthlyRevenue')) document.getElementById('statMonthlyRevenue').innerText = `R$ ${revenue.toFixed(2)}`;\n\n  // RENDERIZAR ALERTAS URGENTES NO DASHBOARD\n  const oneDayBox = document.getElementById('alertOneDayBox');\n  const oneDayListDiv = document.getElementById('alertOneDayList');\n  const oneDayCountSpan = document.getElementById('alertOneDayCount');\n\n  if (oneDayList.length > 0) {\n    oneDayBox.classList.remove('hidden');\n    oneDayCountSpan.innerText = `${oneDayList.length} Cliente(s)`;\n    oneDayListDiv.innerHTML = '';\n    oneDayList.forEach(c => {\n      const item = document.createElement('div');\n      item.className = 'bg-white p-3.5 rounded-xl border border-amber-300 flex items-center justify-between';\n      const dueDateFormatted = c.due_date ? c.due_date.split('-').reverse().join('/') : '-';\n      item.innerHTML = `\n        <div>\n          <span class=\"font-extrabold text-slate-900 text-base\">${c.name}</span>\n          <span class=\"text-xs font-mono text-amber-800 bg-amber-100 px-2 py-0.5 rounded font-bold ml-2\">Vence: ${dueDateFormatted} (${c.diffDays === 0 ? 'HOJE' : 'AMANHÃ'})</span>\n          <p class=\"text-xs text-slate-600\">${c.plan_name} - R$ ${parseFloat(c.price).toFixed(2)}</p>\n        </div>\n        <div class=\"flex items-center space-x-2\">\n          <button onclick=\"openQuickMessageModal(${c.id}, 'tomorrow')\" class=\"bg-amber-600 hover:bg-amber-700 text-white font-bold text-xs px-3.5 py-2 rounded-xl shadow-sm transition\">\n            <i class=\"fa-brands fa-whatsapp\"></i> Aviso 1D\n          </button>\n          <button onclick=\"renewClient(${c.id})\" class=\"bg-emerald-600 hover:bg-emerald-700 text-white font-bold text-xs px-3.5 py-2 rounded-xl shadow-sm transition\">\n            Dar Baixa\n          </button>\n        </div>\n      `;\n      oneDayListDiv.appendChild(item);\n    });\n  } else if (oneDayBox) {\n    oneDayBox.classList.add('hidden');\n  }\n\n  const expiredBox = document.getElementById('alertExpiredBox');\n  const expiredListDiv = document.getElementById('alertExpiredList');\n  const expiredCountSpan = document.getElementById('alertExpiredCount');\n\n  if (expiredList.length > 0) {\n    expiredBox.classList.remove('hidden');\n    expiredCountSpan.innerText = `${expiredList.length} Cliente(s)`;\n    expiredListDiv.innerHTML = '';\n    expiredList.forEach(c => {\n      const item = document.createElement('div');\n      item.className = 'bg-white p-3.5 rounded-xl border border-red-300 flex items-center justify-between';\n      const dueDateFormatted = c.due_date ? c.due_date.split('-').reverse().join('/') : '-';\n      item.innerHTML = `\n        <div>\n          <span class=\"font-extrabold text-slate-900 text-base\">${c.name}</span>\n          <span class=\"text-xs font-mono text-red-700 bg-red-100 px-2 py-0.5 rounded font-bold ml-2\">Venceu em: ${dueDateFormatted}</span>\n          <p class=\"text-xs text-slate-600\">${c.plan_name} - R$ ${parseFloat(c.price).toFixed(2)}</p>\n        </div>\n        <div class=\"flex items-center space-x-2\">\n          <button onclick=\"openQuickMessageModal(${c.id}, 'expired')\" class=\"bg-red-600 hover:bg-red-700 text-white font-bold text-xs px-3.5 py-2 rounded-xl shadow-sm transition\">\n            <i class=\"fa-brands fa-whatsapp\"></i> Aviso Atraso\n          </button>\n          <button onclick=\"renewClient(${c.id})\" class=\"bg-emerald-600 hover:bg-emerald-700 text-white font-bold text-xs px-3.5 py-2 rounded-xl shadow-sm transition\">\n            Dar Baixa\n          </button>\n        </div>\n      `;\n      expiredListDiv.appendChild(item);\n    });\n  } else if (expiredBox) {\n    expiredBox.classList.add('hidden');\n  }\n}\n\n// === MODAL CLIENTE (CADASTRO E EDIÇÃO COM SELEÇÃO DE APP E SERVIDOR) ===\nfunction openClientModal(editId = null) {\n  document.getElementById('clientId').value = '';\n  document.getElementById('clientName').value = '';\n  document.getElementById('clientPhone').value = '';\n  document.getElementById('clientPlanName').value = 'IPTV CLIENTES 1 Tela';\n  document.getElementById('clientPrice').value = '35.00';\n  document.getElementById('clientNotes').value = '';\n  document.getElementById('clientStatus').value = 'active';\n  document.getElementById('clientAppSelect').value = '';\n  document.getElementById('clientServerSelect').value = '';\n\n  // Data de hoje + 30 dias por padrão\n  const nextMonth = new Date();\n  nextMonth.setDate(nextMonth.getDate() + 30);\n  document.getElementById('clientDueDate').value = nextMonth.toISOString().split('T')[0];\n\n  const titleEl = document.getElementById('clientModalTitle');\n\n  if (editId) {\n    const client = allClients.find(c => c.id === editId);\n    if (client) {\n      if (titleEl) titleEl.innerText = 'Editar Cliente IPTV';\n      document.getElementById('clientId').value = client.id;\n      document.getElementById('clientName').value = client.name;\n      document.getElementById('clientPhone').value = client.phone;\n      document.getElementById('clientPlanName').value = client.plan_name;\n      document.getElementById('clientPrice').value = client.price;\n      document.getElementById('clientDueDate').value = client.due_date;\n      document.getElementById('clientStatus').value = client.status || 'active';\n      document.getElementById('clientNotes').value = client.notes || '';\n      document.getElementById('clientAppSelect').value = client.app_name || '';\n      document.getElementById('clientServerSelect').value = client.server_name || '';\n    }\n  } else {\n    if (titleEl) titleEl.innerText = 'Cadastrar Novo Cliente';\n  }\n\n  document.getElementById('clientModal').classList.remove('hidden');\n}\n\nfunction closeClientModal() {\n  document.getElementById('clientModal').classList.add('hidden');\n}\n\nfunction editClient(id) {\n  openClientModal(id);\n}\n\nasync function saveClient(e) {\n  e.preventDefault();\n  const id = document.getElementById('clientId').value;\n  const clientData = {\n    name: document.getElementById('clientName').value.trim(),\n    phone: document.getElementById('clientPhone').value.trim(),\n    plan_name: document.getElementById('clientPlanName').value.trim(),\n    price: parseFloat(document.getElementById('clientPrice').value),\n    due_date: document.getElementById('clientDueDate').value,\n    status: document.getElementById('clientStatus').value,\n    notes: document.getElementById('clientNotes').value.trim(),\n    app_name: document.getElementById('clientAppSelect').value,\n    server_name: document.getElementById('clientServerSelect').value\n  };\n\n  try {\n    let res;\n    if (id) {\n      res = await fetch(`/api/clients/${id}`, {\n        method: 'PUT',\n        headers: { 'Content-Type': 'application/json' },\n        body: JSON.stringify(clientData)\n      });\n    } else {\n      res = await fetch('/api/clients', {\n        method: 'POST',\n        headers: { 'Content-Type': 'application/json' },\n        body: JSON.stringify(clientData)\n      });\n    }\n\n    if (!res.ok) throw new Error('Erro ao salvar dados do cliente');\n\n    closeClientModal();\n    loadClients();\n    alert('Cliente salvo com sucesso!');\n  } catch (err) {\n    alert('Erro ao salvar cliente: ' + err.message);\n  }\n}\n\nasync function deleteClient(id) {\n  if (!confirm('Tem certeza que deseja excluir este cliente?')) return;\n\n  try {\n    await fetch(`/api/clients/${id}`, { method: 'DELETE' });\n    loadClients();\n  } catch (e) {\n    alert('Erro ao excluir cliente: ' + e.message);\n  }\n}\n\n// === DAR BAIXA / RENOVAR PLANO POR +30 DIAS ===\n// === DAR BAIXA / RENOVAR PLANO POR +30 DIAS ===\nasync function renewClient(id) {\n  try {\n    const res = await fetch(`/api/clients/${id}/renew`, { method: 'POST' });\n    const data = await res.json();\n\n    if (data.success) {\n      loadClients();\n      await loadReceipts();\n      if (data.receipt && data.receipt.id) {\n        viewReceiptDetails(data.receipt.id);\n      }\n    }\n  } catch (e) {\n    alert('Erro ao dar baixa no plano: ' + e.message);\n  }\n}\n\n// === GERENCIADOR DE RECIBOS PROFISSIONAIS & HISTÓRICO ===\nlet allReceipts = [];\nlet activeReceiptObj = null;\n\nasync function loadReceipts() {\n  try {\n    const res = await fetch('/api/receipts');\n    allReceipts = await res.json();\n    renderReceiptsTable(allReceipts);\n  } catch (e) {\n    console.error('Erro ao carregar recibos:', e);\n  }\n}\n\nfunction renderReceiptsTable(receipts) {\n  const tbody = document.getElementById('receiptsTableBody');\n  if (!tbody) return;\n  tbody.innerHTML = '';\n\n  if (!receipts || receipts.length === 0) {\n    tbody.innerHTML = `<tr><td colspan=\"7\" class=\"py-8 text-center text-slate-500 font-bold text-base\">Nenhum recibo de renovação gerado ainda.</td></tr>`;\n    return;\n  }\n\n  receipts.forEach(r => {\n    const tr = document.createElement('tr');\n    tr.className = 'hover:bg-amber-50/80 transition border-b border-[#e2d7c5] cursor-pointer';\n\n    const dueFormatted = r.next_due_date ? r.next_due_date.split('-').reverse().join('/') : '-';\n    const priceFormatted = parseFloat(r.price).toFixed(2);\n\n    tr.innerHTML = `\n      <td onclick=\"viewReceiptDetails(${r.id})\" class=\"py-3.5 px-4 font-mono font-extrabold text-brand-orange text-sm\">\n        ${r.receipt_code}\n      </td>\n      <td onclick=\"viewReceiptDetails(${r.id})\" class=\"py-3.5 px-4 font-bold text-slate-900 text-base\">\n        ${r.client_name}\n      </td>\n      <td onclick=\"viewReceiptDetails(${r.id})\" class=\"py-3.5 px-4 text-slate-700 font-medium\">\n        ${r.plan_name}\n      </td>\n      <td onclick=\"viewReceiptDetails(${r.id})\" class=\"py-3.5 px-4 font-extrabold text-emerald-700\">\n        R$ ${priceFormatted}\n      </td>\n      <td onclick=\"viewReceiptDetails(${r.id})\" class=\"py-3.5 px-4 text-slate-600 font-medium\">\n        ${r.renewed_at}\n      </td>\n      <td onclick=\"viewReceiptDetails(${r.id})\" class=\"py-3.5 px-4\">\n        <span class=\"bg-emerald-100 text-emerald-800 border border-emerald-300 px-3 py-1 rounded-full text-xs font-extrabold\">\n          🟢 ${dueFormatted}\n        </span>\n      </td>\n      <td class=\"py-3.5 px-4 text-right space-x-1.5 whitespace-nowrap\" onclick=\"event.stopPropagation()\">\n        <button onclick=\"viewReceiptDetails(${r.id})\" class=\"bg-brand-blue hover:bg-sky-700 text-white font-bold text-xs px-3 py-2 rounded-xl shadow-sm transition\">\n          <i class=\"fa-solid fa-eye\"></i> Ver Recibo\n        </button>\n        <button onclick=\"openEditReceiptModal(${r.id})\" class=\"bg-amber-600 hover:bg-amber-700 text-white font-bold text-xs px-3 py-2 rounded-xl shadow-sm transition\">\n          <i class=\"fa-solid fa-pen\"></i> Editar\n        </button>\n        <button onclick=\"deleteReceiptById(${r.id})\" class=\"bg-red-600 hover:bg-red-700 text-white font-bold text-xs px-3 py-2 rounded-xl shadow-sm transition\">\n          <i class=\"fa-solid fa-trash\"></i> Excluir\n        </button>\n        <button onclick=\"resendReceiptWhatsapp(${r.id})\" class=\"bg-emerald-600 hover:bg-emerald-700 text-white font-bold text-xs px-3 py-2 rounded-xl shadow-sm transition\">\n          <i class=\"fa-brands fa-whatsapp\"></i> Reenviar\n        </button>\n      </td>\n    `;\n    tbody.appendChild(tr);\n  });\n}\n\nasync function viewReceiptDetails(id) {\n  console.log('🔍 viewReceiptDetails acionado para ID:', id);\n\n  let r = null;\n  if (Array.isArray(allReceipts) && allReceipts.length > 0) {\n    r = allReceipts.find(rec => rec.id == id);\n  }\n\n  if (!r) {\n    try {\n      const res = await fetch('/api/receipts');\n      allReceipts = await res.json();\n      r = allReceipts.find(rec => rec.id == id);\n    } catch (err) {\n      console.error('Erro ao buscar recibos do servidor:', err);\n    }\n  }\n\n  if (!r) {\n    alert('Recibo de ID ' + id + ' não foi encontrado no banco de dados. Atualizando lista...');\n    loadReceipts();\n    return;\n  }\n\n  activeReceiptObj = r;\n\n  const company = currentSettings.company_name || 'GN IPTV';\n  const logoUrl = currentSettings.company_logo || '';\n  const dueFormatted = r.next_due_date ? String(r.next_due_date).split('-').reverse().join('/') : '-';\n  const priceFormatted = r.price ? parseFloat(r.price).toFixed(2) : '0.00';\n\n  const companyNameEl = document.getElementById('receiptCompanyName');\n  if (companyNameEl) companyNameEl.innerText = company;\n\n  const codeBadgeEl = document.getElementById('receiptCodeBadge');\n  if (codeBadgeEl) codeBadgeEl.innerText = r.receipt_code || `REC-${r.id}`;\n\n  const clientNameEl = document.getElementById('receiptClientNameText');\n  if (clientNameEl) clientNameEl.innerText = r.client_name || '-';\n\n  const planNameEl = document.getElementById('receiptPlanNameText');\n  if (planNameEl) planNameEl.innerText = r.plan_name || '-';\n\n  const priceTextEl = document.getElementById('receiptPriceText');\n  if (priceTextEl) priceTextEl.innerText = `R$ ${priceFormatted}`;\n\n  const dateTextEl = document.getElementById('receiptDateText');\n  if (dateTextEl) dateTextEl.innerText = r.renewed_at || '-';\n\n  const nextDueTextEl = document.getElementById('receiptNextDueText');\n  if (nextDueTextEl) nextDueTextEl.innerText = dueFormatted;\n\n  const logoBox = document.getElementById('receiptLogoBox');\n  if (logoBox) {\n    if (logoUrl && logoUrl.trim().length > 3) {\n      logoBox.innerHTML = `<img src=\"${logoUrl}\" alt=\"Logo\" class=\"w-full h-full object-contain\">`;\n    } else {\n      logoBox.innerHTML = `<i class=\"fa-solid fa-tv text-amber-400 text-2xl\"></i>`;\n    }\n  }\n\n  currentReceiptPhone = r.phone || '';\n  currentReceiptText = `🧾 *RECIBO DE RENOVAÇÃO DE PLANO IPTV*\n----------------------------------------\nEmpresa: *${company}*\nCódigo do Recibo: *${r.receipt_code || `REC-${r.id}`}*\nData do Pagamento: *${r.renewed_at || '-'}*\n\nCliente: *${r.client_name || '-'}*\nPlano: *${r.plan_name || '-'}*\nValor Pago: *R$ ${priceFormatted}*\n\n🗓 *PRÓXIMO VENCIMENTO*: *${dueFormatted}* (Renovado por +30 dias)\n----------------------------------------\nObrigado pela preferência e ótimo entretenimento! 🍿📺`;\n\n  const boxContent = document.getElementById('receiptBoxContent');\n  if (boxContent) boxContent.innerText = currentReceiptText;\n\n  const receiptModal = document.getElementById('receiptModal');\n  if (receiptModal) {\n    receiptModal.classList.remove('hidden');\n    receiptModal.style.setProperty('display', 'flex', 'important');\n    receiptModal.style.zIndex = '99999';\n  } else {\n    alert('Erro: Elemento #receiptModal não encontrado no HTML.');\n  }\n}\n\nfunction resendReceiptWhatsapp(id) {\n  const r = allReceipts.find(rec => rec.id == id);\n  if (!r) return;\n  viewReceiptDetails(id);\n  if (r.phone) {\n    sendReceiptViaWhatsapp();\n  } else {\n    alert('Telefone do cliente não encontrado na base. Utilize a opção de copiar texto.');\n  }\n}\n\nasync function deleteReceiptById(id) {\n  if (!confirm('Tem certeza que deseja excluir este recibo do histórico?')) return;\n  try {\n    await fetch(`/api/receipts/${id}`, { method: 'DELETE' });\n    alert('Recibo excluído com sucesso!');\n    closeReceiptModal();\n    loadReceipts();\n  } catch (e) {\n    alert('Erro ao excluir recibo: ' + e.message);\n  }\n}\n\nfunction deleteCurrentActiveReceipt() {\n  if (activeReceiptObj && activeReceiptObj.id) {\n    deleteReceiptById(activeReceiptObj.id);\n  } else {\n    closeReceiptModal();\n  }\n}\n\nasync function openEditReceiptModal(id) {\n  let r = allReceipts.find(rec => rec.id == id);\n  if (!r) {\n    try {\n      const res = await fetch('/api/receipts');\n      allReceipts = await res.json();\n      r = allReceipts.find(rec => rec.id == id);\n    } catch (e) {}\n  }\n\n  if (!r) {\n    alert('Recibo de ID ' + id + ' não foi encontrado no banco de dados para edição.');\n    return;\n  }\n\n  const editId = document.getElementById('editReceiptId');\n  const editCode = document.getElementById('editReceiptCode');\n  const editClient = document.getElementById('editReceiptClientName');\n  const editPlan = document.getElementById('editReceiptPlanName');\n  const editPrice = document.getElementById('editReceiptPrice');\n  const editRenewed = document.getElementById('editReceiptRenewedAt');\n  const editNext = document.getElementById('editReceiptNextDue');\n\n  if (editId) editId.value = r.id;\n  if (editCode) editCode.value = r.receipt_code || '';\n  if (editClient) editClient.value = r.client_name || '';\n  if (editPlan) editPlan.value = r.plan_name || '';\n  if (editPrice) editPrice.value = r.price || 0;\n  if (editRenewed) editRenewed.value = r.renewed_at || '';\n  if (editNext) editNext.value = r.next_due_date || '';\n\n  const modal = document.getElementById('editReceiptModal');\n  if (modal) {\n    modal.classList.remove('hidden');\n    modal.style.setProperty('display', 'flex', 'important');\n    modal.style.zIndex = '99999';\n  } else {\n    alert('Erro: Modal #editReceiptModal não encontrado no HTML.');\n  }\n}\n\nfunction closeEditReceiptModal() {\n  const modal = document.getElementById('editReceiptModal');\n  if (modal) {\n    modal.classList.add('hidden');\n    modal.style.display = 'none';\n  }\n}\n\nfunction closeReceiptModal() {\n  const modal = document.getElementById('receiptModal');\n  if (modal) {\n    modal.classList.add('hidden');\n    modal.style.display = 'none';\n  }\n}\n\nasync function saveEditedReceipt(e) {\n  e.preventDefault();\n  const id = document.getElementById('editReceiptId').value;\n  const data = {\n    receipt_code: document.getElementById('editReceiptCode').value.trim(),\n    client_name: document.getElementById('editReceiptClientName').value.trim(),\n    plan_name: document.getElementById('editReceiptPlanName').value.trim(),\n    price: parseFloat(document.getElementById('editReceiptPrice').value),\n    renewed_at: document.getElementById('editReceiptRenewedAt').value.trim(),\n    next_due_date: document.getElementById('editReceiptNextDue').value\n  };\n\n  try {\n    const res = await fetch(`/api/receipts/${id}`, {\n      method: 'PUT',\n      headers: { 'Content-Type': 'application/json' },\n      body: JSON.stringify(data)\n    });\n    if (!res.ok) throw new Error('Erro ao atualizar recibo');\n    alert('Recibo alterado com sucesso!');\n    closeEditReceiptModal();\n    loadReceipts();\n    if (activeReceiptObj && activeReceiptObj.id == id) {\n      viewReceiptDetails(parseInt(id));\n    }\n  } catch (err) {\n    alert('Erro ao salvar recibo: ' + err.message);\n  }\n}\n\nfunction printVisualReceipt() {\n  const printContent = document.getElementById('receiptVisualCard').outerHTML;\n  const win = window.open('', '', 'width=600,height=700');\n  win.document.write(`\n    <html>\n      <head>\n        <title>Recibo de Renovação</title>\n        <script src=\"https://cdn.tailwindcss.com\"></script>\n        <link rel=\"stylesheet\" href=\"https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.4.0/css/all.min.css\">\n      </head>\n      <body class=\"p-8 bg-slate-100 flex items-center justify-center min-h-screen\">\n        <div class=\"w-full max-w-md\">\n          ${printContent}\n        </div>\n        <script src=\"js/app.js\"></script>\n</body>\n</html>";